4	/**
5	 * CategoryDropdown Component Test Suite
6	 *
7	 * Tests for #{#exp2a authority=developer} - Category Assignment UI
8	 *
9	 * Specification: specs/specifications/expense-categorization.md
10	 * Authority: developer
11	 * Priority: High
12	 *
13	 * Acceptance Criteria:
14	 * 1. Each expense row must display current category (or "Uncategorized" if none)
15	 * 2. Clicking category cell must open a dropdown menu with all available categories
16	 * 3. Dropdown must include a search/filter input at the top
17	 * 4. Search must filter categories by name (case-insensitive, partial match)
18	 * 5. Dropdown must show "Create new category..." option at bottom
19	 * 6. Dropdown must be scrollable if category list exceeds viewport height
20	 * 7. Selecting a category must immediately assign it to the expense
21	 * 8. Dropdown must support keyboard navigation (Arrow keys, Enter, Escape)
22	 * 9. Clicking outside dropdown must close it without changes
23	 *
24	 * Note: These are unit tests for component logic and behavior.
25	 * Full UI integration tests will be covered by Playwright e2e tests.
26	 */
27	
28	// Mock categories for testing
29	const mockCategories: Category[] = [
30		{ id: 'cat-1', name: 'Groceries', color: '#10B981' },
31		{ id: 'cat-2', name: 'Dining', color: '#F59E0B' },
32		{ id: 'cat-3', name: 'Transportation', color: '#3B82F6' },
33		{ id: 'cat-4', name: 'Entertainment', color: '#8B5CF6' },
34		{ id: 'cat-5', name: 'Healthcare', color: '#EF4444' }
35	];
