37	describe('CategoryDropdown - #{#exp2a} Category Assignment UI', () => {
38		describe('Criterion 1: Display current category or "Uncategorized"', () => {
39			/**
40			 * Helper function to determine display text based on current category
41			 * This implements the logic that will be in CategoryDropdown.svelte
42			 */
43			function getCategoryDisplayText(currentCategory: Category | null): string {
44				return currentCategory?.name ?? 'Uncategorized';
45			}
46	
47			it('should return "Uncategorized" when no category is assigned', () => {
48				const displayText = getCategoryDisplayText(null);
49				expect(displayText).toBe('Uncategorized');
50			});
51	
52			it('should return the category name when assigned', () => {
53				const displayText = getCategoryDisplayText(mockCategories[0]);
54				expect(displayText).toBe('Groceries');
55			});
56	
57			it('should handle category with color property', () => {
58				const category = mockCategories[0];
59				expect(category).toHaveProperty('color');
60				expect(category.color).toBe('#10B981');
61			});
62		});
63	
64		describe('Criterion 4: Search filters categories by name', () => {
65			/**
66			 * Helper function to filter categories by search query
67			 * This implements the filtering logic for the dropdown
68			 */
69			function filterCategories(categories: Category[], searchQuery: string): Category[] {
70				if (!searchQuery || searchQuery.trim() === '') {
71					return categories;
72				}
73	
74				const query = searchQuery.toLowerCase();
75				return categories.filter((category) => category.name.toLowerCase().includes(query));
76			}
77	
78			it('should filter categories based on search query (case-insensitive)', () => {
79				const filtered = filterCategories(mockCategories, 'gro');
80				expect(filtered).toHaveLength(1);
81				expect(filtered[0].name).toBe('Groceries');
82			});
83	
84			it('should filter categories with case-insensitive matching', () => {
85				const filtered = filterCategories(mockCategories, 'GRO');
86				expect(filtered).toHaveLength(1);
87				expect(filtered[0].name).toBe('Groceries');
88			});
89	
90			it('should support partial match filtering', () => {
91				const filtered = filterCategories(mockCategories, 'tai');
92				expect(filtered).toHaveLength(1);
93				expect(filtered[0].name).toBe('Entertainment');
94			});
95	
96			it('should return all categories when search is empty', () => {
97				const filtered = filterCategories(mockCategories, '');
98				expect(filtered).toHaveLength(mockCategories.length);
99				expect(filtered).toEqual(mockCategories);
100			});
101	
102			it('should return all categories when search is whitespace', () => {
103				const filtered = filterCategories(mockCategories, '   ');
104				expect(filtered).toHaveLength(mockCategories.length);
105			});
106	
107			it('should return empty array when no categories match', () => {
108				const filtered = filterCategories(mockCategories, 'zzz');
109				expect(filtered).toHaveLength(0);
110			});
111	
112			it('should match categories by substring anywhere in name', () => {
113				const filtered = filterCategories(mockCategories, 'ing');
114				expect(filtered).toHaveLength(1);
115				expect(filtered[0].name).toBe('Dining');
116			});
117	
118			it('should handle special characters in search query', () => {
119				const categoriesWithSpecial = [
120					...mockCategories,
121					{ id: 'cat-6', name: 'Food & Beverage', color: '#000000' }
122				];
123				const filtered = filterCategories(categoriesWithSpecial, '&');
124				expect(filtered).toHaveLength(1);
125				expect(filtered[0].name).toBe('Food & Beverage');
126			});
127		});
