129		describe('Criterion 8: Keyboard navigation support', () => {
130			/**
131			 * Helper function to handle keyboard navigation logic
132			 * Returns the new selected index based on key press
133			 */
134			function handleKeyboardNavigation(key: string, currentIndex: number, maxIndex: number): number {
135				switch (key) {
136					case 'ArrowDown':
137						return currentIndex < maxIndex ? currentIndex + 1 : currentIndex;
138					case 'ArrowUp':
139						return currentIndex > 0 ? currentIndex - 1 : currentIndex;
140					default:
141						return currentIndex;
142				}
143			}
144	
145			it('should move to next item with ArrowDown', () => {
146				const newIndex = handleKeyboardNavigation('ArrowDown', 0, 4);
147				expect(newIndex).toBe(1);
148			});
149	
150			it('should move to previous item with ArrowUp', () => {
151				const newIndex = handleKeyboardNavigation('ArrowUp', 2, 4);
152				expect(newIndex).toBe(1);
153			});
154	
155			it('should not move past last item with ArrowDown', () => {
156				const newIndex = handleKeyboardNavigation('ArrowDown', 4, 4);
157				expect(newIndex).toBe(4);
158			});
159	
160			it('should not move before first item with ArrowUp', () => {
161				const newIndex = handleKeyboardNavigation('ArrowUp', 0, 4);
162				expect(newIndex).toBe(0);
163			});
164	
165			it('should handle navigation in filtered list', () => {
166				const filteredCategories = filterCategories(mockCategories, 'g');
167				const maxIndex = filteredCategories.length - 1;
168				const newIndex = handleKeyboardNavigation('ArrowDown', 0, maxIndex);
169				expect(newIndex).toBeLessThanOrEqual(maxIndex);
170			});
171	
172			it('should handle single item list', () => {
173				const newIndexDown = handleKeyboardNavigation('ArrowDown', 0, 0);
174				const newIndexUp = handleKeyboardNavigation('ArrowUp', 0, 0);
175				expect(newIndexDown).toBe(0);
176				expect(newIndexUp).toBe(0);
177			});
178		});
