180		describe('Criterion 7: Selecting category assigns it immediately', () => {
181			/**
182			 * Helper function to simulate category selection
183			 * Returns true if selection was successful
184			 */
185			function selectCategory(category: Category, onSelect: (cat: Category) => void): boolean {
