604			describe('Criterion 5: Save new category on Enter or Create button', () => {
605				/**
606				 * Helper to validate new category input before creation
607				 */
608				interface ValidationResult {
609					isValid: boolean;
610					error: string | null;
611				}
612	
613				function validateNewCategory(name: string, existingCategories: Category[]): ValidationResult {
614					const trimmedName = name.trim();
615	
616					// Check empty name
617					if (trimmedName.length === 0) {
618						return { isValid: false, error: 'Category name required' };
619					}
620	
621					// Check max length
622					if (trimmedName.length > 100) {
623						return { isValid: false, error: 'Category name must be 100 characters or less' };
624					}
625	
626					// Check duplicate
627					if (isDuplicateCategoryName(trimmedName, existingCategories)) {
628						return { isValid: false, error: 'Category already exists' };
629					}
630	
631					return { isValid: true, error: null };
632				}
633	
634				/**
635				 * Helper to check duplicate (reused from previous tests)
636				 */
637				function isDuplicateCategoryName(
638					categoryName: string,
639					existingCategories: Category[]
640				): boolean {
641					const normalizedName = categoryName.trim().toLowerCase();
642					return existingCategories.some((cat) => cat.name.toLowerCase() === normalizedName);
643				}
644	
645				it('should validate and allow creation of valid category', () => {
646					const result = validateNewCategory('New Category', mockCategories);
647					expect(result.isValid).toBe(true);
648					expect(result.error).toBeNull();
649				});
650	
651				it('should reject empty category name with error message', () => {
652					const result = validateNewCategory('', mockCategories);
653					expect(result.isValid).toBe(false);
654					expect(result.error).toBe('Category name required');
655				});
656	
657				it('should reject duplicate category name with error message', () => {
658					const result = validateNewCategory('Groceries', mockCategories);
659					expect(result.isValid).toBe(false);
660					expect(result.error).toBe('Category already exists');
661				});
662	
663				it('should reject category name exceeding 100 characters', () => {
