import { describe, it, expect, vi } from 'vitest';
import type { Category } from '$lib/types/Category';

/**
 * CategoryDropdown Component Test Suite
 *
 * Tests for #{#exp2a authority=developer} - Category Assignment UI
 *
 * Specification: specs/specifications/expense-categorization.md
 * Authority: developer
 * Priority: High
 *
 * Acceptance Criteria:
 * 1. Each expense row must display current category (or "Uncategorized" if none)
 * 2. Clicking category cell must open a dropdown menu with all available categories
 * 3. Dropdown must include a search/filter input at the top
 * 4. Search must filter categories by name (case-insensitive, partial match)
 * 5. Dropdown must show "Create new category..." option at bottom
 * 6. Dropdown must be scrollable if category list exceeds viewport height
 * 7. Selecting a category must immediately assign it to the expense
 * 8. Dropdown must support keyboard navigation (Arrow keys, Enter, Escape)
 * 9. Clicking outside dropdown must close it without changes
 *
 * Note: These are unit tests for component logic and behavior.
 * Full UI integration tests will be covered by Playwright e2e tests.
 */

// Mock categories for testing
const mockCategories: Category[] = [
	{ id: 'cat-1', name: 'Groceries', color: '#10B981' },
	{ id: 'cat-2', name: 'Dining', color: '#F59E0B' },
	{ id: 'cat-3', name: 'Transportation', color: '#3B82F6' },
	{ id: 'cat-4', name: 'Entertainment', color: '#8B5CF6' },
	{ id: 'cat-5', name: 'Healthcare', color: '#EF4444' }
];

describe('CategoryDropdown - #{#exp2a} Category Assignment UI', () => {
	describe('Criterion 1: Display current category or "Uncategorized"', () => {
		/**
		 * Helper function to determine display text based on current category
		 * This implements the logic that will be in CategoryDropdown.svelte
		 */
		function getCategoryDisplayText(currentCategory: Category | null): string {
			return currentCategory?.name ?? 'Uncategorized';
		}

		it('should return "Uncategorized" when no category is assigned', () => {
			const displayText = getCategoryDisplayText(null);
			expect(displayText).toBe('Uncategorized');
		});

		it('should return the category name when assigned', () => {
			const displayText = getCategoryDisplayText(mockCategories[0]);
			expect(displayText).toBe('Groceries');
		});

		it('should handle category with color property', () => {
			const category = mockCategories[0];
			expect(category).toHaveProperty('color');
			expect(category.color).toBe('#10B981');
		});
	});

	describe('Criterion 4: Search filters categories by name', () => {
		/**
		 * Helper function to filter categories by search query
		 * This implements the filtering logic for the dropdown
		 */
		function filterCategories(categories: Category[], searchQuery: string): Category[] {
			if (!searchQuery || searchQuery.trim() === '') {
				return categories;
			}

			const query = searchQuery.toLowerCase();
			return categories.filter((category) => category.name.toLowerCase().includes(query));
		}

		it('should filter categories based on search query (case-insensitive)', () => {
			const filtered = filterCategories(mockCategories, 'gro');
			expect(filtered).toHaveLength(1);
			expect(filtered[0].name).toBe('Groceries');
		});

		it('should filter categories with case-insensitive matching', () => {
			const filtered = filterCategories(mockCategories, 'GRO');
			expect(filtered).toHaveLength(1);
			expect(filtered[0].name).toBe('Groceries');
		});

		it('should support partial match filtering', () => {
			const filtered = filterCategories(mockCategories, 'tai');
			expect(filtered).toHaveLength(1);
			expect(filtered[0].name).toBe('Entertainment');
		});

		it('should return all categories when search is empty', () => {
			const filtered = filterCategories(mockCategories, '');
			expect(filtered).toHaveLength(mockCategories.length);
			expect(filtered).toEqual(mockCategories);
		});

		it('should return all categories when search is whitespace', () => {
			const filtered = filterCategories(mockCategories, '   ');
			expect(filtered).toHaveLength(mockCategories.length);
		});

		it('should return empty array when no categories match', () => {
			const filtered = filterCategories(mockCategories, 'zzz');
			expect(filtered).toHaveLength(0);
		});

		it('should match categories by substring anywhere in name', () => {
			const filtered = filterCategories(mockCategories, 'ing');
			expect(filtered).toHaveLength(1);
			expect(filtered[0].name).toBe('Dining');
		});

		it('should handle special characters in search query', () => {
			const categoriesWithSpecial = [
				...mockCategories,
				{ id: 'cat-6', name: 'Food & Beverage', color: '#000000' }
			];
			const filtered = filterCategories(categoriesWithSpecial, '&');
			expect(filtered).toHaveLength(1);
			expect(filtered[0].name).toBe('Food & Beverage');
		});
	});

	describe('Criterion 8: Keyboard navigation support', () => {
		/**
		 * Helper function to handle keyboard navigation logic
		 * Returns the new selected index based on key press
		 */
		function handleKeyboardNavigation(key: string, currentIndex: number, maxIndex: number): number {
			switch (key) {
				case 'ArrowDown':
					return currentIndex < maxIndex ? currentIndex + 1 : currentIndex;
				case 'ArrowUp':
					return currentIndex > 0 ? currentIndex - 1 : currentIndex;
				default:
					return currentIndex;
			}
		}

		it('should move to next item with ArrowDown', () => {
			const newIndex = handleKeyboardNavigation('ArrowDown', 0, 4);
			expect(newIndex).toBe(1);
		});

		it('should move to previous item with ArrowUp', () => {
			const newIndex = handleKeyboardNavigation('ArrowUp', 2, 4);
			expect(newIndex).toBe(1);
		});

		it('should not move past last item with ArrowDown', () => {
			const newIndex = handleKeyboardNavigation('ArrowDown', 4, 4);
			expect(newIndex).toBe(4);
		});

		it('should not move before first item with ArrowUp', () => {
			const newIndex = handleKeyboardNavigation('ArrowUp', 0, 4);
			expect(newIndex).toBe(0);
		});

		it('should handle navigation in filtered list', () => {
			const filteredCategories = filterCategories(mockCategories, 'g');
			const maxIndex = filteredCategories.length - 1;
			const newIndex = handleKeyboardNavigation('ArrowDown', 0, maxIndex);
			expect(newIndex).toBeLessThanOrEqual(maxIndex);
		});

		it('should handle single item list', () => {
			const newIndexDown = handleKeyboardNavigation('ArrowDown', 0, 0);
			const newIndexUp = handleKeyboardNavigation('ArrowUp', 0, 0);
			expect(newIndexDown).toBe(0);
			expect(newIndexUp).toBe(0);
		});
	});

	describe('Criterion 7: Selecting category assigns it immediately', () => {
		/**
		 * Helper function to simulate category selection
		 * Returns true if selection was successful
		 */
		function selectCategory(category: Category, onSelect: (cat: Category) => void): boolean {
			if (!category) return false;
			onSelect(category);
			return true;
		}

		it('should call onSelect callback when category is selected', () => {
			const mockOnSelect = vi.fn();
			const result = selectCategory(mockCategories[0], mockOnSelect);

			expect(result).toBe(true);
			expect(mockOnSelect).toHaveBeenCalledWith(mockCategories[0]);
			expect(mockOnSelect).toHaveBeenCalledTimes(1);
		});

		it('should pass the correct category to callback', () => {
			const mockOnSelect = vi.fn();
			selectCategory(mockCategories[2], mockOnSelect);

			expect(mockOnSelect).toHaveBeenCalledWith(mockCategories[2]);
			expect(mockOnSelect.mock.calls[0][0].name).toBe('Transportation');
		});

		it('should not call callback if category is null', () => {
			const mockOnSelect = vi.fn();
			const result = selectCategory(null as any, mockOnSelect);

			expect(result).toBe(false);
			expect(mockOnSelect).not.toHaveBeenCalled();
		});
	});

	describe('Component State Management', () => {
		/**
		 * Helper function to manage dropdown open/close state
		 */
		function toggleDropdown(isOpen: boolean): boolean {
			return !isOpen;
		}

		function closeDropdown(): boolean {
			return false;
		}

		function openDropdown(): boolean {
			return true;
		}

		it('should toggle dropdown state', () => {
			let isOpen = false;
			isOpen = toggleDropdown(isOpen);
			expect(isOpen).toBe(true);

			isOpen = toggleDropdown(isOpen);
			expect(isOpen).toBe(false);
		});

		it('should close dropdown when requested', () => {
			const isOpen = closeDropdown();
			expect(isOpen).toBe(false);
		});

		it('should open dropdown when requested', () => {
			const isOpen = openDropdown();
			expect(isOpen).toBe(true);
		});
	});

	describe('Component Props Validation', () => {
		it('should accept currentCategory as Category object', () => {
			const category: Category = mockCategories[0];
			expect(category).toHaveProperty('id');
			expect(category).toHaveProperty('name');
			expect(category).toHaveProperty('color');
		});

		it('should accept currentCategory as null', () => {
			const category: Category | null = null;
			expect(category).toBeNull();
		});

		it('should accept categories as array of Category objects', () => {
			const categories: Category[] = mockCategories;
			expect(Array.isArray(categories)).toBe(true);
			expect(categories.length).toBeGreaterThan(0);
			expect(categories[0]).toHaveProperty('name');
		});

		it('should accept onCategorySelect as function', () => {
			const onSelect = vi.fn();
			expect(typeof onSelect).toBe('function');
		});

		it('should handle empty categories array', () => {
			const categories: Category[] = [];
			const filtered = filterCategories(categories, 'test');
			expect(filtered).toEqual([]);
		});
	});

	describe('Category Data Validation', () => {
		it('should validate category has required id field', () => {
			const category = mockCategories[0];
			expect(category.id).toBeDefined();
			expect(typeof category.id).toBe('string');
			expect(category.id.length).toBeGreaterThan(0);
		});

		it('should validate category has required name field', () => {
			const category = mockCategories[0];
			expect(category.name).toBeDefined();
			expect(typeof category.name).toBe('string');
			expect(category.name.length).toBeGreaterThan(0);
		});

		it('should validate category has required color field', () => {
			const category = mockCategories[0];
			expect(category.color).toBeDefined();
			expect(typeof category.color).toBe('string');
			expect(category.color).toMatch(/^#[0-9A-F]{6}$/i);
		});

		it('should validate all mock categories have correct structure', () => {
			mockCategories.forEach((category) => {
				expect(category).toHaveProperty('id');
				expect(category).toHaveProperty('name');
				expect(category).toHaveProperty('color');
				expect(category.color).toMatch(/^#/);
			});
		});
	});

	describe('Search Query Normalization', () => {
		/**
		 * Helper function to normalize search query
		 */
		function normalizeSearchQuery(query: string): string {
			return query.trim().toLowerCase();
		}

		it('should trim whitespace from search query', () => {
			const normalized = normalizeSearchQuery('  test  ');
			expect(normalized).toBe('test');
		});

		it('should convert search query to lowercase', () => {
			const normalized = normalizeSearchQuery('TEST');
			expect(normalized).toBe('test');
		});

		it('should handle empty string', () => {
			const normalized = normalizeSearchQuery('');
			expect(normalized).toBe('');
		});

		it('should handle whitespace-only string', () => {
			const normalized = normalizeSearchQuery('   ');
			expect(normalized).toBe('');
		});
	});

	describe('Dropdown Behavior Logic', () => {
		/**
		 * Helper to determine if dropdown should close on a given action
		 */
		function shouldCloseOnAction(action: string): boolean {
			const closingActions = ['escape', 'select', 'clickOutside'];
			return closingActions.includes(action);
		}

		it('should close dropdown on Escape key', () => {
			expect(shouldCloseOnAction('escape')).toBe(true);
		});

		it('should close dropdown on category select', () => {
			expect(shouldCloseOnAction('select')).toBe(true);
		});

		it('should close dropdown on outside click', () => {
			expect(shouldCloseOnAction('clickOutside')).toBe(true);
		});

		it('should not close dropdown on search input', () => {
			expect(shouldCloseOnAction('search')).toBe(false);
		});

		it('should not close dropdown on arrow key navigation', () => {
			expect(shouldCloseOnAction('arrowDown')).toBe(false);
		});
	});

	describe('Integration Logic', () => {
		/**
		 * Helper function to handle keyboard navigation logic (duplicate for integration tests)
		 */
		function handleKeyboardNavigation(key: string, currentIndex: number, maxIndex: number): number {
			switch (key) {
				case 'ArrowDown':
					return currentIndex < maxIndex ? currentIndex + 1 : currentIndex;
				case 'ArrowUp':
					return currentIndex > 0 ? currentIndex - 1 : currentIndex;
				default:
					return currentIndex;
			}
		}

		/**
		 * Helper function to simulate category selection (duplicate for integration tests)
		 */
		function selectCategory(category: Category, onSelect: (cat: Category) => void): boolean {
			if (!category) return false;
			onSelect(category);
			return true;
		}

		it('should filter and navigate through filtered results', () => {
			// Filter to only "Groceries"
			const filtered = filterCategories(mockCategories, 'gro');
			expect(filtered).toHaveLength(1);

			// Navigate in filtered list (should stay at index 0)
			const maxIndex = filtered.length - 1;
			const newIndex = handleKeyboardNavigation('ArrowDown', 0, maxIndex);
			expect(newIndex).toBe(0); // Can't go beyond single item
		});

		it('should reset search and show all categories', () => {
			// Start with filtered list
			let filtered = filterCategories(mockCategories, 'gro');
			expect(filtered).toHaveLength(1);

			// Clear search
			filtered = filterCategories(mockCategories, '');
			expect(filtered).toHaveLength(mockCategories.length);
		});

		it('should maintain category selection with different search states', () => {
			const mockOnSelect = vi.fn();

			// Select category from filtered list
			const filtered = filterCategories(mockCategories, 'gro');
			selectCategory(filtered[0], mockOnSelect);

			expect(mockOnSelect).toHaveBeenCalledWith(mockCategories[0]);
		});
	});

	describe('#{#exp3b} Create New Category Inline', () => {
		/**
		 * Tests for #{#exp3b authority=developer} - Create New Category Inline
		 *
		 * Specification: specs/specifications/expense-categorization.md
		 * Authority: developer
		 * Priority: High
		 *
		 * Acceptance Criteria:
		 * 1. Dropdown must show "+ Create new category..." option at bottom
		 * 2. Clicking option must show inline input field for category name
		 * 3. Input must appear in dropdown (no modal navigation)
		 * 4. User must be able to enter category name and optional color
		 * 5. Pressing Enter or clicking "Create" must save new category
		 * 6. New category must immediately appear in dropdown list
		 * 7. New category must be auto-selected for the current expense
		 * 8. Duplicate category names must show error: "Category already exists"
		 * 9. Empty category name must show error: "Category name required"
		 * 10. Maximum category name length: 100 characters
		 */

		describe('Criterion 2-3: Inline input field appears in dropdown', () => {
			/**
			 * Helper to manage inline creation mode state
			 */
			function toggleInlineCreationMode(isInCreationMode: boolean): boolean {
				return !isInCreationMode;
			}

			it('should toggle inline creation mode when "+ Create new category..." is clicked', () => {
				let isInCreationMode = false;
				isInCreationMode = toggleInlineCreationMode(isInCreationMode);
				expect(isInCreationMode).toBe(true);
			});

			it('should show inline creation mode in dropdown (not modal)', () => {
				const isInCreationMode = true;
				expect(isInCreationMode).toBe(true);
			});

			it('should cancel inline creation mode', () => {
				let isInCreationMode = true;
				isInCreationMode = toggleInlineCreationMode(isInCreationMode);
				expect(isInCreationMode).toBe(false);
			});
		});

		describe('Criterion 4: User can enter category name and optional color', () => {
			/**
			 * Helper to manage new category input state
			 */
			interface NewCategoryInput {
				name: string;
				color: string;
			}

			function createNewCategoryInput(name: string, color: string = ''): NewCategoryInput {
				return { name: name.trim(), color };
			}

			it('should accept category name input', () => {
				const input = createNewCategoryInput('New Category');
				expect(input.name).toBe('New Category');
			});

			it('should trim whitespace from category name', () => {
				const input = createNewCategoryInput('  New Category  ');
				expect(input.name).toBe('New Category');
			});

			it('should accept optional color input', () => {
				const input = createNewCategoryInput('New Category', '#FF5733');
				expect(input.color).toBe('#FF5733');
			});

			it('should handle empty color (defaults to empty string)', () => {
				const input = createNewCategoryInput('New Category');
				expect(input.color).toBe('');
			});
		});

		describe('Criterion 8: Duplicate category validation', () => {
			/**
			 * Helper to check if category name already exists (case-insensitive)
			 */
			function isDuplicateCategoryName(
				categoryName: string,
				existingCategories: Category[]
			): boolean {
				const normalizedName = categoryName.trim().toLowerCase();
				return existingCategories.some((cat) => cat.name.toLowerCase() === normalizedName);
			}

			it('should detect exact duplicate category name', () => {
				const isDuplicate = isDuplicateCategoryName('Groceries', mockCategories);
				expect(isDuplicate).toBe(true);
			});

			it('should detect duplicate category name (case-insensitive)', () => {
				const isDuplicate = isDuplicateCategoryName('GROCERIES', mockCategories);
				expect(isDuplicate).toBe(true);
			});

			it('should detect duplicate with different casing', () => {
				const isDuplicate = isDuplicateCategoryName('groceries', mockCategories);
				expect(isDuplicate).toBe(true);
			});

			it('should allow new unique category name', () => {
				const isDuplicate = isDuplicateCategoryName('New Category', mockCategories);
				expect(isDuplicate).toBe(false);
			});

			it('should handle whitespace in duplicate detection', () => {
				const isDuplicate = isDuplicateCategoryName('  Groceries  ', mockCategories);
				expect(isDuplicate).toBe(true);
			});
		});

		describe('Criterion 9: Empty category name validation', () => {
			/**
			 * Helper to validate category name is not empty
			 */
			function isValidCategoryName(categoryName: string): boolean {
				return categoryName.trim().length > 0;
			}

			it('should reject empty category name', () => {
				expect(isValidCategoryName('')).toBe(false);
			});

			it('should reject whitespace-only category name', () => {
				expect(isValidCategoryName('   ')).toBe(false);
			});

			it('should accept valid category name', () => {
				expect(isValidCategoryName('New Category')).toBe(true);
			});

			it('should accept category name with leading/trailing spaces', () => {
				expect(isValidCategoryName('  New Category  ')).toBe(true);
			});
		});

		describe('Criterion 10: Maximum category name length validation', () => {
			/**
			 * Helper to validate category name length
			 */
			function isWithinMaxLength(categoryName: string, maxLength: number = 100): boolean {
				return categoryName.trim().length <= maxLength;
			}

			it('should accept category name within 100 characters', () => {
				const name = 'A'.repeat(100);
				expect(isWithinMaxLength(name, 100)).toBe(true);
			});

			it('should reject category name exceeding 100 characters', () => {
				const name = 'A'.repeat(101);
				expect(isWithinMaxLength(name, 100)).toBe(false);
			});

			it('should accept category name exactly at 100 characters', () => {
				const name = 'A'.repeat(100);
				expect(isWithinMaxLength(name, 100)).toBe(true);
			});

			it('should handle edge case of 1 character', () => {
				expect(isWithinMaxLength('A', 100)).toBe(true);
			});
		});

		describe('Criterion 5: Save new category on Enter or Create button', () => {
			/**
			 * Helper to validate new category input before creation
			 */
			interface ValidationResult {
				isValid: boolean;
				error: string | null;
			}

			function validateNewCategory(name: string, existingCategories: Category[]): ValidationResult {
				const trimmedName = name.trim();

				// Check empty name
				if (trimmedName.length === 0) {
					return { isValid: false, error: 'Category name required' };
				}

				// Check max length
				if (trimmedName.length > 100) {
					return { isValid: false, error: 'Category name must be 100 characters or less' };
				}

				// Check duplicate
				if (isDuplicateCategoryName(trimmedName, existingCategories)) {
					return { isValid: false, error: 'Category already exists' };
				}

				return { isValid: true, error: null };
			}

			/**
			 * Helper to check duplicate (reused from previous tests)
			 */
			function isDuplicateCategoryName(
				categoryName: string,
				existingCategories: Category[]
			): boolean {
				const normalizedName = categoryName.trim().toLowerCase();
				return existingCategories.some((cat) => cat.name.toLowerCase() === normalizedName);
			}

			it('should validate and allow creation of valid category', () => {
				const result = validateNewCategory('New Category', mockCategories);
				expect(result.isValid).toBe(true);
				expect(result.error).toBeNull();
			});

			it('should reject empty category name with error message', () => {
				const result = validateNewCategory('', mockCategories);
				expect(result.isValid).toBe(false);
				expect(result.error).toBe('Category name required');
			});

			it('should reject duplicate category name with error message', () => {
				const result = validateNewCategory('Groceries', mockCategories);
				expect(result.isValid).toBe(false);
				expect(result.error).toBe('Category already exists');
			});

			it('should reject category name exceeding 100 characters', () => {
				const longName = 'A'.repeat(101);
				const result = validateNewCategory(longName, mockCategories);
				expect(result.isValid).toBe(false);
				expect(result.error).toBe('Category name must be 100 characters or less');
			});

			it('should trim whitespace before validation', () => {
				const result = validateNewCategory('  New Category  ', mockCategories);
				expect(result.isValid).toBe(true);
			});
		});

		describe('Criterion 6-7: New category appears and auto-selected', () => {
			/**
			 * Helper to add new category to list and return updated list
			 */
			function addCategoryToList(
				newCategory: Category,
				existingCategories: Category[]
			): Category[] {
				return [...existingCategories, newCategory];
			}

			/**
			 * Helper to auto-select newly created category
			 */
			function autoSelectCategory(category: Category, onSelect: (cat: Category) => void): void {
				onSelect(category);
			}

			it('should add new category to categories list', () => {
				const newCategory: Category = {
					id: 'cat-6',
					name: 'New Category',
					color: '#FF5733'
				};
				const updatedCategories = addCategoryToList(newCategory, mockCategories);

				expect(updatedCategories).toHaveLength(mockCategories.length + 1);
				expect(updatedCategories).toContainEqual(newCategory);
			});

			it('should auto-select newly created category', () => {
				const mockOnSelect = vi.fn();
				const newCategory: Category = {
					id: 'cat-6',
					name: 'New Category',
					color: '#FF5733'
				};

				autoSelectCategory(newCategory, mockOnSelect);

				expect(mockOnSelect).toHaveBeenCalledWith(newCategory);
				expect(mockOnSelect).toHaveBeenCalledTimes(1);
			});

			it('should verify new category appears in filtered list', () => {
				const newCategory: Category = {
					id: 'cat-6',
					name: 'New Category',
					color: '#FF5733'
				};
				const updatedCategories = addCategoryToList(newCategory, mockCategories);
				const filtered = filterCategories(updatedCategories, 'new');

				expect(filtered).toHaveLength(1);
				expect(filtered[0].name).toBe('New Category');
			});
		});

		describe('Color validation for new category', () => {
			/**
			 * Helper to validate hex color format
			 */
			function isValidHexColor(color: string): boolean {
				if (!color || color === '') return true; // Optional color
				return /^#[0-9A-F]{6}$/i.test(color);
			}

			it('should accept valid hex color', () => {
				expect(isValidHexColor('#FF5733')).toBe(true);
			});

			it('should accept empty color (optional)', () => {
				expect(isValidHexColor('')).toBe(true);
			});

			it('should reject invalid hex color format', () => {
				expect(isValidHexColor('FF5733')).toBe(false); // Missing #
			});

			it('should reject short hex color', () => {
				expect(isValidHexColor('#FFF')).toBe(false); // Too short
			});

			it('should reject long hex color', () => {
				expect(isValidHexColor('#FF57331')).toBe(false); // Too long
			});

			it('should accept hex color with lowercase letters', () => {
				expect(isValidHexColor('#ff5733')).toBe(true);
			});

			it('should accept hex color with uppercase letters', () => {
				expect(isValidHexColor('#FF5733')).toBe(true);
			});
		});

		describe('Inline creation workflow integration', () => {
			/**
			 * Complete workflow simulation
			 */
			interface CreationWorkflowState {
				isInCreationMode: boolean;
				newCategoryName: string;
				newCategoryColor: string;
				error: string | null;
			}

			function initializeCreationWorkflow(): CreationWorkflowState {
				return {
					isInCreationMode: false,
					newCategoryName: '',
					newCategoryColor: '',
					error: null
				};
			}

			function startInlineCreation(state: CreationWorkflowState): CreationWorkflowState {
				return {
					...state,
					isInCreationMode: true,
					newCategoryName: '',
					newCategoryColor: '',
					error: null
				};
			}

			function cancelInlineCreation(state: CreationWorkflowState): CreationWorkflowState {
				return {
					...state,
					isInCreationMode: false,
					newCategoryName: '',
					newCategoryColor: '',
					error: null
				};
			}

			it('should initialize creation workflow in default state', () => {
				const state = initializeCreationWorkflow();
				expect(state.isInCreationMode).toBe(false);
				expect(state.newCategoryName).toBe('');
				expect(state.error).toBeNull();
			});

			it('should start inline creation mode', () => {
				let state = initializeCreationWorkflow();
				state = startInlineCreation(state);

				expect(state.isInCreationMode).toBe(true);
				expect(state.newCategoryName).toBe('');
				expect(state.error).toBeNull();
			});

			it('should cancel inline creation and reset state', () => {
				let state = initializeCreationWorkflow();
				state = startInlineCreation(state);
				state.newCategoryName = 'Test';
				state = cancelInlineCreation(state);

				expect(state.isInCreationMode).toBe(false);
				expect(state.newCategoryName).toBe('');
				expect(state.error).toBeNull();
			});
		});
	});
});

// Helper function implementations that will be used in the component
function filterCategories(categories: Category[], searchQuery: string): Category[] {
	if (!searchQuery || searchQuery.trim() === '') {
		return categories;
	}

	const query = searchQuery.toLowerCase();
	return categories.filter((category) => category.name.toLowerCase().includes(query));
}

