import { describe, it, expect, vi } from 'vitest';
import { render } from 'vitest-browser-svelte';
import FilteredEmptyState from './FilteredEmptyState.svelte';

/**
 * Component test for the shared "filters are hiding everything" empty state.
 *
 * This block was duplicated byte-for-byte across the expenses, receipts and
 * transactions list tables (RF-03). These tests pin its observable behaviour so
 * the extraction is safe and survives future markup changes — they exercise the
 * public props (count / itemNoun / onClear), never the internal markup.
 */
describe('FilteredEmptyState', () => {
	it('shows the "no results" heading and how many items the filters hid', async () => {
		const screen = render(FilteredEmptyState, { count: 3, itemNoun: 'expense', onClear: () => {} });

		await expect.element(screen.getByRole('heading', { name: 'No results found' })).toBeVisible();
		await expect.element(screen.getByText(/hiding all 3 expenses/)).toBeVisible();
	});

	it('uses the singular noun when exactly one item is hidden', async () => {
		const screen = render(FilteredEmptyState, { count: 1, itemNoun: 'receipt', onClear: () => {} });

		await expect.element(screen.getByText(/hiding all 1 receipt\./)).toBeVisible();
	});

	it('calls onClear when the "Clear all filters" button is clicked', async () => {
		const onClear = vi.fn();
		const screen = render(FilteredEmptyState, { count: 2, itemNoun: 'transaction', onClear });

		await screen.getByRole('button', { name: 'Clear all filters' }).click();

		expect(onClear).toHaveBeenCalledOnce();
	});
});

