82	describe('#{#tcf1a} Transaction Credit/Bank Type Filter State Management', () => {
83		describe('Filter Logic', () => {
84			/**
85			 * #{#tcf1a} Criterion 6: The filter must work in combination with existing date, vendor, and amount filters
86			 *
87			 * This function represents the updated applyClientFilters logic with credit/bank type filtering
88			 */
89			function applyClientFilters(
90				txns: TransactionRow[],
91				filters: {
92					urlDateFrom?: string | null;
93					urlDateTo?: string | null;
94					filterVendor?: string;
95					filterAmountMin?: string;
96					filterAmountMax?: string;
97					filterCreditCardType?: CreditCardType | 'all';
98				}
99			): TransactionRow[] {
100				return txns.filter((t) => {
101					// Date filter (from URL)
102					if (filters.urlDateFrom && t.transaction_date < filters.urlDateFrom) return false;
103					if (filters.urlDateTo && t.transaction_date > filters.urlDateTo) return false;
104	
105					// Vendor filter
106					if (filters.filterVendor) {
107						const vendorSearch = filters.filterVendor.toLowerCase();
108						const vendor = t.vendor_name.toLowerCase();
109						if (!vendor.includes(vendorSearch)) return false;
110					}
111	
112					// Amount filter
113					if (filters.filterAmountMin) {
114						const minAmount = parseFloat(filters.filterAmountMin);
115						if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
116					}
117					if (filters.filterAmountMax) {
118						const maxAmount = parseFloat(filters.filterAmountMax);
119						if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
120					}
121	
122					// NEW: Credit/bank type filter (#{#tcf1a})
123					if (filters.filterCreditCardType && filters.filterCreditCardType !== 'all') {
124						if (t.credit_card_type !== filters.filterCreditCardType) return false;
125					}
126	
127					return true;
128				});
129			}
130	
131			/**
132			 * #{#tcf1a} Criterion 1-3: Credit/bank type filter must support "All Types" and individual types
133			 */
134			it('should filter transactions by credit card type', () => {
135				const filtered = applyClientFilters(mockTransactions, {
136					filterCreditCardType: 'PC Financial'
137				});
138	
