140				expect(filtered.every((t) => t.credit_card_type === 'PC Financial')).toBe(true);
141				expect(filtered[0].vendor_name).toBe('Amazon');
142				expect(filtered[1].vendor_name).toBe('Safeway');
143			});
144	
145			it('should show all transactions when filter is set to "all"', () => {
146				const filtered = applyClientFilters(mockTransactions, {
147					filterCreditCardType: 'all'
148				});
149	
150				expect(filtered.length).toBe(5);
151				expect(filtered).toEqual(mockTransactions);
152			});
153	
154			it('should return empty array when no transactions match credit card type', () => {
155				const filtered = applyClientFilters(mockTransactions, {
156					filterCreditCardType: 'Simplii Financial'
157				});
158	
159				expect(filtered.length).toBe(0);
160			});
161	
162			/**
163			 * #{#tcf1a} Criterion 6: Filter must work in combination with date filters
164			 */
165			it('should combine credit/bank type filter with date range filter', () => {
166				const filtered = applyClientFilters(mockTransactions, {
167					urlDateFrom: '2025-12-03',
168					urlDateTo: '2025-12-05',
169					filterCreditCardType: 'PC Financial'
170				});
171	
172				expect(filtered.length).toBe(2);
173				expect(filtered.every((t) => t.credit_card_type === 'PC Financial')).toBe(true);
174				expect(filtered.every((t) => t.transaction_date >= '2025-12-03')).toBe(true);
175				expect(filtered.every((t) => t.transaction_date <= '2025-12-05')).toBe(true);
176			});
177	
178			/**
179			 * #{#tcf1a} Criterion 6: Filter must work in combination with vendor filter
180			 */
181			it('should combine credit/bank type filter with vendor filter', () => {
182				const filtered = applyClientFilters(mockTransactions, {
183					filterVendor: 'safe',
184					filterCreditCardType: 'PC Financial'
185				});
186	
