/**
 * Tests for Transactions Page - Credit/Bank Type Filter Features
 *
 * Specification Coverage:
 * - #{#tcf1a} Transaction Credit/Bank Type Filter State Management
 * - #{#tcf1b} Transaction Credit/Bank Type Filter UI Component
 * - #{#tcf2a} Filter Status Display Enhancement
 * - #{#tcf4a} Interaction with Existing Card Type Filter
 *
 * Authority: developer
 * Priority: High (#{#tcf1a}, #{#tcf1b}, #{#tcf4a}), Medium (#{#tcf2a})
 *
 * Note: These are unit/integration tests for page logic.
 * Full UI e2e tests will be covered by Playwright tests.
 */

import { describe, it, expect, beforeEach } from 'vitest';
import type { TransactionRow, CreditCardType } from '$lib/models/Transaction';
import { CREDIT_CARD_TYPES } from '$lib/models/Transaction';

/**
 * Mock transaction data for testing
 */
const mockTransactions: TransactionRow[] = [
	{
		id: 'txn-1',
		family_id: 'fam-1',
		transaction_date: '2025-12-05',
		vendor_name: 'Amazon',
		amount: -123.45,
		credit_card_type: 'PC Financial',
		excluded: false,
		created_at: '2025-12-05T10:00:00Z',
		updated_at: '2025-12-05T10:00:00Z'
	},
	{
		id: 'txn-2',
		family_id: 'fam-1',
		transaction_date: '2025-12-04',
		vendor_name: 'Shell Gas',
		amount: -45.67,
		credit_card_type: 'American Express',
		excluded: false,
		created_at: '2025-12-04T10:00:00Z',
		updated_at: '2025-12-04T10:00:00Z'
	},
	{
		id: 'txn-3',
		family_id: 'fam-1',
		transaction_date: '2025-12-03',
		vendor_name: 'Safeway',
		amount: -89.12,
		credit_card_type: 'PC Financial',
		excluded: false,
		created_at: '2025-12-03T10:00:00Z',
		updated_at: '2025-12-03T10:00:00Z'
	},
	{
		id: 'txn-4',
		family_id: 'fam-1',
		transaction_date: '2025-12-02',
		vendor_name: 'Best Buy',
		amount: -299.99,
		credit_card_type: 'RBC Financial',
		excluded: false,
		created_at: '2025-12-02T10:00:00Z',
		updated_at: '2025-12-02T10:00:00Z'
	},
	{
		id: 'txn-5',
		family_id: 'fam-1',
		transaction_date: '2025-12-01',
		vendor_name: 'Costco',
		amount: -156.78,
		credit_card_type: 'TD Bank',
		excluded: false,
		created_at: '2025-12-01T10:00:00Z',
		updated_at: '2025-12-01T10:00:00Z'
	}
];

describe('#{#tcf1a} Transaction Credit/Bank Type Filter State Management', () => {
	describe('Filter Logic', () => {
		/**
		 * #{#tcf1a} Criterion 6: The filter must work in combination with existing date, vendor, and amount filters
		 *
		 * This function represents the updated applyClientFilters logic with credit/bank type filtering
		 */
		function applyClientFilters(
			txns: TransactionRow[],
			filters: {
				urlDateFrom?: string | null;
				urlDateTo?: string | null;
				filterVendor?: string;
				filterAmountMin?: string;
				filterAmountMax?: string;
				filterCreditCardType?: CreditCardType | 'all';
			}
		): TransactionRow[] {
			return txns.filter((t) => {
				// Date filter (from URL)
				if (filters.urlDateFrom && t.transaction_date < filters.urlDateFrom) return false;
				if (filters.urlDateTo && t.transaction_date > filters.urlDateTo) return false;

				// Vendor filter
				if (filters.filterVendor) {
					const vendorSearch = filters.filterVendor.toLowerCase();
					const vendor = t.vendor_name.toLowerCase();
					if (!vendor.includes(vendorSearch)) return false;
				}

				// Amount filter
				if (filters.filterAmountMin) {
					const minAmount = parseFloat(filters.filterAmountMin);
					if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
				}
				if (filters.filterAmountMax) {
					const maxAmount = parseFloat(filters.filterAmountMax);
					if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
				}

				// NEW: Credit/bank type filter (#{#tcf1a})
				if (filters.filterCreditCardType && filters.filterCreditCardType !== 'all') {
					if (t.credit_card_type !== filters.filterCreditCardType) return false;
				}

				return true;
			});
		}

		/**
		 * #{#tcf1a} Criterion 1-3: Credit/bank type filter must support "All Types" and individual types
		 */
		it('should filter transactions by credit card type', () => {
			const filtered = applyClientFilters(mockTransactions, {
				filterCreditCardType: 'PC Financial'
			});

			expect(filtered.length).toBe(2);
			expect(filtered.every((t) => t.credit_card_type === 'PC Financial')).toBe(true);
			expect(filtered[0].vendor_name).toBe('Amazon');
			expect(filtered[1].vendor_name).toBe('Safeway');
		});

		it('should show all transactions when filter is set to "all"', () => {
			const filtered = applyClientFilters(mockTransactions, {
				filterCreditCardType: 'all'
			});

			expect(filtered.length).toBe(5);
			expect(filtered).toEqual(mockTransactions);
		});

		it('should return empty array when no transactions match credit card type', () => {
			const filtered = applyClientFilters(mockTransactions, {
				filterCreditCardType: 'Simplii Financial'
			});

			expect(filtered.length).toBe(0);
		});

		/**
		 * #{#tcf1a} Criterion 6: Filter must work in combination with date filters
		 */
		it('should combine credit/bank type filter with date range filter', () => {
			const filtered = applyClientFilters(mockTransactions, {
				urlDateFrom: '2025-12-03',
				urlDateTo: '2025-12-05',
				filterCreditCardType: 'PC Financial'
			});

			expect(filtered.length).toBe(2);
			expect(filtered.every((t) => t.credit_card_type === 'PC Financial')).toBe(true);
			expect(filtered.every((t) => t.transaction_date >= '2025-12-03')).toBe(true);
			expect(filtered.every((t) => t.transaction_date <= '2025-12-05')).toBe(true);
		});

		/**
		 * #{#tcf1a} Criterion 6: Filter must work in combination with vendor filter
		 */
		it('should combine credit/bank type filter with vendor filter', () => {
			const filtered = applyClientFilters(mockTransactions, {
				filterVendor: 'safe',
				filterCreditCardType: 'PC Financial'
			});

			expect(filtered.length).toBe(1);
			expect(filtered[0].vendor_name).toBe('Safeway');
			expect(filtered[0].credit_card_type).toBe('PC Financial');
		});

		/**
		 * #{#tcf1a} Criterion 6: Filter must work in combination with amount filters
		 */
		it('should combine credit/bank type filter with amount range filter', () => {
			const filtered = applyClientFilters(mockTransactions, {
				filterAmountMin: '100',
				filterAmountMax: '200',
				filterCreditCardType: 'PC Financial'
			});

			expect(filtered.length).toBe(1);
			expect(filtered[0].vendor_name).toBe('Amazon');
			expect(filtered[0].credit_card_type).toBe('PC Financial');
			expect(Math.abs(filtered[0].amount)).toBeGreaterThanOrEqual(100);
			expect(Math.abs(filtered[0].amount)).toBeLessThanOrEqual(200);
		});

		/**
		 * #{#tcf1a} Criterion 6: Filter must work with all filters combined
		 */
		it('should combine all filters including credit/bank type', () => {
			const filtered = applyClientFilters(mockTransactions, {
				urlDateFrom: '2025-12-01',
				urlDateTo: '2025-12-05',
				filterVendor: 'safe', // Contains 'safe': only Safeway
				filterAmountMin: '50',
				filterAmountMax: '150',
				filterCreditCardType: 'PC Financial'
			});

			// Should only match Safeway: PC Financial, contains 'safe', amount 89.12 (between 50-150), in date range
			expect(filtered.length).toBe(1);
			expect(filtered[0].vendor_name).toBe('Safeway');
			expect(filtered[0].credit_card_type).toBe('PC Financial');
		});
	});

	describe('Filter State Management', () => {
		/**
		 * #{#tcf1a} Criterion 4-5: Filter state stored as temporary until "Apply Filters" clicked
		 * This simulates the state management logic
		 */
		interface FilterState {
			tempFilterCreditCardType: CreditCardType | 'all';
			filterCreditCardType: CreditCardType | 'all';
		}

		function applyFilterValues(state: FilterState): FilterState {
			return {
				...state,
				filterCreditCardType: state.tempFilterCreditCardType
			};
		}

		function clearClientFilters(state: FilterState): FilterState {
			return {
				...state,
				tempFilterCreditCardType: 'all',
				filterCreditCardType: 'all'
			};
		}

		it('should apply temporary filter value when applyFilterValues is called', () => {
			const initialState: FilterState = {
				tempFilterCreditCardType: 'American Express',
				filterCreditCardType: 'all'
			};

			const newState = applyFilterValues(initialState);

			expect(newState.filterCreditCardType).toBe('American Express');
			expect(newState.tempFilterCreditCardType).toBe('American Express');
		});

		it('should clear both temporary and active filter when clearClientFilters is called', () => {
			const initialState: FilterState = {
				tempFilterCreditCardType: 'RBC Financial',
				filterCreditCardType: 'RBC Financial'
			};

			const newState = clearClientFilters(initialState);

			expect(newState.tempFilterCreditCardType).toBe('all');
			expect(newState.filterCreditCardType).toBe('all');
		});
	});
});

describe('#{#tcf2a} Filter Status Display Enhancement', () => {
	/**
	 * #{#tcf2a} Criterion 3: hasActiveFilters reactive statement must include credit/bank type check
	 */
	function hasActiveFilters(filters: {
		urlDateFrom?: string | null;
		urlDateTo?: string | null;
		filterVendor?: string;
		filterAmountMin?: string;
		filterAmountMax?: string;
		filterCreditCardType?: CreditCardType | 'all';
	}): boolean {
		return !!(
			filters.urlDateFrom ||
			filters.urlDateTo ||
			filters.filterVendor ||
			filters.filterAmountMin ||
			filters.filterAmountMax ||
			(filters.filterCreditCardType && filters.filterCreditCardType !== 'all')
		);
	}

	it('should return true when credit/bank type filter is active', () => {
		expect(
			hasActiveFilters({
				filterCreditCardType: 'PC Financial'
			})
		).toBe(true);
	});

	it('should return false when credit/bank type filter is set to "all"', () => {
		expect(
			hasActiveFilters({
				filterCreditCardType: 'all'
			})
		).toBe(false);
	});

	it('should return false when no filters are active', () => {
		expect(
			hasActiveFilters({
				filterCreditCardType: 'all'
			})
		).toBe(false);
	});

	it('should return true when credit/bank type filter is combined with other filters', () => {
		expect(
			hasActiveFilters({
				urlDateFrom: '2025-12-01',
				filterVendor: 'Amazon',
				filterCreditCardType: 'American Express'
			})
		).toBe(true);
	});

	it('should return true when only date filter is active (not credit/bank type)', () => {
		expect(
			hasActiveFilters({
				urlDateFrom: '2025-12-01',
				filterCreditCardType: 'all'
			})
		).toBe(true);
	});

	it('should return true when only vendor filter is active (not credit/bank type)', () => {
		expect(
			hasActiveFilters({
				filterVendor: 'Amazon',
				filterCreditCardType: 'all'
			})
		).toBe(true);
	});
});

describe('#{#tcf4a} Interaction with Existing Card Type Filter', () => {
	/**
	 * #{#tcf4a} Criterion 8-9: Server-side filter affects allTransactions, client-side affects displayed transactions
	 */
	it('should demonstrate server-side filter narrows data load', () => {
		// Simulate server-side filtering (affects what gets loaded into allTransactions)
		const allTransactionsAfterServerFilter = mockTransactions.filter(
			(t) => t.credit_card_type === 'PC Financial'
		);

		expect(allTransactionsAfterServerFilter.length).toBe(2);
		expect(
			allTransactionsAfterServerFilter.every((t) => t.credit_card_type === 'PC Financial')
		).toBe(true);
	});

	it('should demonstrate client-side filter further filters server-loaded data', () => {
		// Step 1: Server-side filter loads only PC Financial transactions
		const allTransactionsAfterServerFilter = mockTransactions.filter(
			(t) => t.credit_card_type === 'PC Financial'
		);

		// Step 2: Client-side filter applies vendor filter to loaded data
		function applyClientFilters(
			txns: TransactionRow[],
			filters: { filterVendor?: string }
		): TransactionRow[] {
			return txns.filter((t) => {
				if (filters.filterVendor) {
					const vendorSearch = filters.filterVendor.toLowerCase();
					const vendor = t.vendor_name.toLowerCase();
					if (!vendor.includes(vendorSearch)) return false;
				}
				return true;
			});
		}

		const displayedTransactions = applyClientFilters(allTransactionsAfterServerFilter, {
			filterVendor: 'Amazon'
		});

		expect(displayedTransactions.length).toBe(1);
		expect(displayedTransactions[0].vendor_name).toBe('Amazon');
		expect(displayedTransactions[0].credit_card_type).toBe('PC Financial');
	});

	/**
	 * #{#tcf4a} Criterion 1-2: Server-side filter remains unchanged and independent
	 */
	it('should allow both filters to be different values simultaneously', () => {
		// Server-side: Load American Express transactions
		const serverFilterType: CreditCardType = 'American Express';
		const allTransactionsAfterServerFilter = mockTransactions.filter(
			(t) => t.credit_card_type === serverFilterType
		);

		// Client-side: Try to filter by PC Financial (should return empty since server only loaded Amex)
		const clientFilterType: CreditCardType = 'PC Financial';
		const displayedTransactions = allTransactionsAfterServerFilter.filter(
			(t) => t.credit_card_type === clientFilterType
		);

		expect(allTransactionsAfterServerFilter.length).toBe(1); // Server loaded 1 Amex transaction
		expect(displayedTransactions.length).toBe(0); // Client filter for PC Financial finds none
	});
});

describe('#{#tcf1b} Credit Card Types Constant', () => {
	/**
	 * #{#tcf1b} Criterion 4: Subsequent options must list all types from CREDIT_CARD_TYPES array
	 */
	it('should have CREDIT_CARD_TYPES available for dropdown options', () => {
		expect(CREDIT_CARD_TYPES).toBeDefined();
		expect(Array.isArray(CREDIT_CARD_TYPES)).toBe(true);
		expect(CREDIT_CARD_TYPES.length).toBeGreaterThan(0);
	});

	it('should include expected credit card and bank types', () => {
