31		import { emptySelection } from '$lib/utils/selectionModel';
32	
33		const transactionService = new TransactionService(supabase);
34	
35		let allTransactions: TransactionRow[] = $state([]);
36		let familyId: string | null = $state(null);
37		let transactionSelection = $state(emptySelection());
38		let error: string | null = $state(null);
39		let importing = $state(false);
40		let selectedCardType: CreditCardType = $state('PC Financial');
41		let includeIgnored = $state(false);
42		let editRow: TransactionRow | null = $state(null);
43		let deleting = new SvelteSet<string>();
44		let bulkDeleting = $state(false);
45		let successMessage: string | null = $state(null);
46	
47		// #{#sdf2c} Read date filters from URL query parameters
48		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
49		let urlDateFrom = $derived(urlDateFilter.dateFrom);
50		let urlDateTo = $derived(urlDateFilter.dateTo);
51	
52		// Client-side filters - temporary values for inputs.
53		// Seed from the URL params directly (not from the urlDate* deriveds) so the
54		// initializer doesn't capture a reactive value; the $effect below keeps them
55		// in sync when the URL changes.
56		let tempFilterDateFrom = $state(readDateFilter($page.url.searchParams).dateFrom);
57		let tempFilterDateTo = $state(readDateFilter($page.url.searchParams).dateTo);
58		let tempFilterVendor = $state('');
59		let tempFilterAmountMin = $state('');
60		let tempFilterAmountMax = $state('');
61		let tempFilterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
62	
63		// Sync temp date values when URL changes
64		$effect(() => {
65			tempFilterDateFrom = urlDateFrom;
66			tempFilterDateTo = urlDateTo;
67		});
68	
69		// Active filter values used for filtering (non-date filters only)
70		let filterVendor = $state('');
71		let filterAmountMin = $state('');
72		let filterAmountMax = $state('');
73		let filterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
74	
75		async function loadTransactions(): Promise<void> {
76			if (!familyId) return;
77			error = null;
78			try {
79				// DataTable sorts client-side over the full in-memory list; load in a stable order.
80				// Card/bank type is filtered client-side via the Filters panel, so the query
81				// only needs the excluded-rows toggle.
82				allTransactions = await transactionService.list(familyId, {
83					sort: 'transaction_date',
84					direction: 'desc',
85					includeExcluded: includeIgnored
86				});
87			} catch (e) {
88				error = e instanceof Error ? e.message : 'Failed to load transactions';
89			}
90		}
91	
92		async function getDefaultFamily(): Promise<string | null> {
93			const { data: familyMembers } = await supabase
94				.from('family_members')
95				.select('family_id, is_default')
96				.eq('user_id', (await supabase.auth.getUser()).data.user?.id)
97				.order('is_default', { ascending: false })
98				.limit(1);
99	
100			return familyMembers?.[0]?.family_id || null;
101		}
102	
103		onMount(async () => {
104			familyId = await getDefaultFamily();
105			if (familyId) {
106				await loadTransactions();
107			} else {
108				error = 'No family found. Please create or join a family first.';
109			}
110		});
111	
112		async function onFileSelected(e: Event): Promise<void> {
113			const input = e.target as HTMLInputElement;
114			const file = input.files?.[0];
115			if (!file || !familyId) return;
116	
117			importing = true;
118			error = null;
119			successMessage = null;
120	
121			try {
122				const result = await transactionService.importFromCSV(familyId, file, selectedCardType);
123	
124				if (result.errors.length > 0) {
125					error = result.errors.join('\n');
126				}
127	
128				if (result.imported > 0 || result.skipped > 0) {
129					// #{#tid3a} Import summary UX
130					if (result.imported === 0 && result.skipped > 0) {
131						successMessage = `No new transactions — ${result.skipped} already in your records`;
132					} else if (result.skipped > 0) {
133						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}, skipped ${result.skipped} duplicate${result.skipped === 1 ? '' : 's'}`;
134					} else {
135						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}`;
136					}
137					await loadTransactions();
138				}
139			} catch (e) {
140				error = e instanceof Error ? e.message : 'Failed to import transactions';
141			} finally {
142				importing = false;
143				input.value = '';
144			}
145		}
146	
147		async function deleteTransaction(t: TransactionRow): Promise<void> {
148			if (!confirm('Delete this transaction?')) return;
149			deleting.add(t.id);
150			error = null;
151			try {
152				await transactionService.delete(t.id);
153				allTransactions = allTransactions.filter((x) => x.id !== t.id);
154				successMessage = 'Transaction deleted';
155			} catch (e) {
156				error = e instanceof Error ? e.message : 'Failed to delete transaction';
157			} finally {
158				deleting.delete(t.id);
159			}
160		}
161	
162		// #{#tbd1a} Selection-based bulk delete — only the checked rows.
163		async function deleteSelected(): Promise<void> {
164			const ids = Array.from(transactionSelection.selected);
165			if (ids.length === 0) return;
166			if (!confirm(`Delete ${ids.length} selected transaction${ids.length === 1 ? '' : 's'}?`)) {
167				return;
168			}
169	
170			bulkDeleting = true;
171			error = null;
172			const original = [...allTransactions];
173			// Optimistic update — remove from UI immediately
174			allTransactions = allTransactions.filter((t) => !transactionSelection.selected.has(t.id));
175	
176			try {
177				await transactionService.deleteByIds(ids);
178				successMessage = `${ids.length} transaction${ids.length === 1 ? '' : 's'} deleted`;
179				transactionSelection = emptySelection();
180			} catch (e) {
181				// Rollback on failure
182				allTransactions = original;
183				error = e instanceof Error ? e.message : 'Failed to delete transactions';
184			} finally {
185				bulkDeleting = false;
186			}
187		}
188	
189		async function toggleExcluded(t: TransactionRow): Promise<void> {
190			error = null;
191			try {
192				const updated = await transactionService.toggleExcluded(t.id, !t.excluded);
193				allTransactions = allTransactions.map((x) => (x.id === updated.id ? updated : x));
194				successMessage = updated.excluded ? 'Transaction excluded' : 'Transaction included';
195			} catch (e) {
196				error = e instanceof Error ? e.message : 'Failed to update transaction';
197			}
198		}
199	
200		async function saveEdit(): Promise<void> {
201			if (!editRow) return;
202			error = null;
203			try {
204				const updated = await transactionService.update(editRow.id, {
205					vendor_name: editRow.vendor_name,
206					amount: editRow.amount,
207					transaction_date: editRow.transaction_date,
208					credit_card_type: editRow.credit_card_type
209				});
210				allTransactions = allTransactions.map((t) => (t.id === updated.id ? updated : t));
211				editRow = null;
212				successMessage = 'Transaction updated';
213			} catch (e) {
214				error = e instanceof Error ? e.message : 'Failed to save transaction';
215			}
216		}
217	
218		function formatAmount(amount: number): string {
219			const abs = Math.abs(amount);
220			const formatted = abs.toFixed(2);
221			return amount < 0 ? `-$${formatted}` : `$${formatted}`;
222		}
223	
224		function getAmountClass(amount: number): string {
225			return amount < 0 ? 'text-red-600' : 'text-green-600';
226		}
227	
228		function applyClientFilters(txns: TransactionRow[]): TransactionRow[] {
229			return txns.filter((t) => {
230				// #{#sdf1b} Filter by date range using URL parameters
231				if (!matchesDateRange(t.transaction_date, urlDateFrom, urlDateTo)) return false;
232	
233				// Filter by vendor name (local state)
234				if (filterVendor) {
235					const vendorSearch = filterVendor.toLowerCase();
236					const vendor = t.vendor_name.toLowerCase();
237					if (!vendor.includes(vendorSearch)) return false;
238				}
239	
240				// Filter by amount range (local state)
241				if (filterAmountMin) {
242					const minAmount = parseFloat(filterAmountMin);
243					if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
244				}
245				if (filterAmountMax) {
246					const maxAmount = parseFloat(filterAmountMax);
247					if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
248				}
249	
250				// #{#tcf1a} Filter by credit/bank type (local state)
251				if (filterCreditCardType !== 'all') {
252					if (t.credit_card_type !== filterCreditCardType) return false;
253				}
254	
255				return true;
256			});
257		}
258	
259		function applyFilterValues(): void {
260			// #{#sdf2c} Update URL with date filters
261			const params = applyDateFilterParams(
262				$page.url.searchParams,
263				tempFilterDateFrom,
264				tempFilterDateTo
265			);
266			goto(resolve(`/transactions?${params.toString()}`), {
267				replaceState: true,
268				keepFocus: true
269			});
270	
271			// Apply non-date filters locally
272			filterVendor = tempFilterVendor;
273			filterAmountMin = tempFilterAmountMin;
274			filterAmountMax = tempFilterAmountMax;
275			filterCreditCardType = tempFilterCreditCardType; // #{#tcf1a}
276		}
277	
278		function clearClientFilters(): void {
279			// #{#sdf2c} Clear URL date filters
280			const params = clearDateFilterParams($page.url.searchParams);
281			goto(resolve(`/transactions?${params.toString()}`), {
282				replaceState: true,
283				keepFocus: true
284			});
285	
286			// Clear local filters
287			tempFilterVendor = '';
288			tempFilterAmountMin = '';
289			tempFilterAmountMax = '';
290			tempFilterCreditCardType = 'all'; // #{#tcf1a}
291			filterVendor = '';
292			filterAmountMin = '';
293			filterAmountMax = '';
294			filterCreditCardType = 'all'; // #{#tcf1a}
295		}
296	
297		// loadTransactions reads familyId and includeIgnored synchronously, so the
298		// effect tracks them both and re-runs when the "Show excluded" toggle changes.
299		$effect(() => {
300			loadTransactions();
301		});
302	
303		let transactions = $derived(applyClientFilters(allTransactions));
304	
305		let hasActiveFilters = $derived(
306			urlDateFrom ||
307				urlDateTo ||
308				filterVendor ||
309				filterAmountMin ||
310				filterAmountMax ||
311				filterCreditCardType !== 'all' // #{#tcf2a}
312		);
