/**
 * Pure client-side filter predicate for the Transactions list page (#{#tcf1a}).
 *
 * The transactions page loads the family's rows once and filters them in memory
 * against the Filters panel (date range + vendor substring + amount range +
 * credit/bank type). That predicate used to live inline in `+page.svelte`, which
 * made it untestable without rendering the page — so its spec re-declared a copy
 * of the logic and asserted against the copy. This module owns the real logic so
 * the page and the tests share one implementation.
 *
 * The reactive `$state`/`$derived`/`goto` wiring stays on the page; only the pure
 * computation lives here. Date matching delegates to the shared `matchesDateRange`
 * so the four list pages keep identical date semantics.
 *
 * @module transactionFilters
 */

import type { TransactionRow, CreditCardType } from '$lib/models/Transaction';
import { matchesDateRange } from './sharedDateFilter';

/** The active filter values the transactions page filters its rows against. */
export interface TransactionFilterCriteria {
	/** Inclusive lower date bound (`YYYY-MM-DD`); `''`/omitted means unbounded. */
	dateFrom?: string;
	/** Inclusive upper date bound (`YYYY-MM-DD`); `''`/omitted means unbounded. */
	dateTo?: string;
	/** Case-insensitive vendor-name substring; `''`/omitted matches everything. */
	vendor?: string;
	/** Minimum absolute amount as a string; blank/`NaN` means no lower bound. */
	amountMin?: string;
	/** Maximum absolute amount as a string; blank/`NaN` means no upper bound. */
	amountMax?: string;
	/** Exact credit/bank type; `'all'`/omitted matches every type. */
	creditCardType?: CreditCardType | 'all';
}

/**
 * Does a transaction row pass every active filter? Amounts are compared by
 * absolute value (rows store expenses as negative), matching the UI's amount box.
 */
export function matchesTransactionFilters(
	t: TransactionRow,
	criteria: TransactionFilterCriteria
): boolean {
	if (!matchesDateRange(t.transaction_date, criteria.dateFrom ?? '', criteria.dateTo ?? '')) {
		return false;
	}

	if (criteria.vendor) {
		if (!t.vendor_name.toLowerCase().includes(criteria.vendor.toLowerCase())) return false;
	}

	if (criteria.amountMin) {
		const min = parseFloat(criteria.amountMin);
		if (!isNaN(min) && Math.abs(t.amount) < min) return false;
	}
	if (criteria.amountMax) {
		const max = parseFloat(criteria.amountMax);
		if (!isNaN(max) && Math.abs(t.amount) > max) return false;
	}

	if (criteria.creditCardType && criteria.creditCardType !== 'all') {
		if (t.credit_card_type !== criteria.creditCardType) return false;
	}

	return true;
}

/**
 * Is any filter active? Drives the "filters are hiding rows" empty state and the
 * Clear-filters affordance (#{#tcf2a}).
 */
export function hasActiveTransactionFilters(criteria: TransactionFilterCriteria): boolean {
	return !!(
		criteria.dateFrom ||
		criteria.dateTo ||
		criteria.vendor ||
		criteria.amountMin ||
		criteria.amountMax ||
		(criteria.creditCardType && criteria.creditCardType !== 'all')
	);
}

