import { describe, it, expect } from 'vitest';
import type { TransactionRow } from '$lib/models/Transaction';
import {
	matchesTransactionFilters,
	hasActiveTransactionFilters
} from './transactionFilters';

/**
 * Real tests for the transactions client-side filter predicate (#{#tcf1a}/#{#tcf2a}).
 *
 * These replace the old `transactions-page-filters.spec.ts`, which re-declared the
 * page's filter logic as local `applyClientFilters` / `hasActiveFilters` copies and
 * asserted against those copies — so the page could break without a failing test.
 * The scenarios below are the same ones that spec pinned, but now exercise the
 * single shared implementation the page actually calls.
 */
const rows: TransactionRow[] = [
	makeRow('txn-1', 'Amazon', -123.45, 'PC Financial', '2025-12-05'),
	makeRow('txn-2', 'Shell Gas', -45.67, 'American Express', '2025-12-04'),
	makeRow('txn-3', 'Safeway', -89.12, 'PC Financial', '2025-12-03'),
	makeRow('txn-4', 'Best Buy', -299.99, 'RBC Financial', '2025-12-02'),
	makeRow('txn-5', 'Costco', -156.78, 'TD Bank', '2025-12-01')
];

function makeRow(
	id: string,
	vendor_name: string,
	amount: number,
	credit_card_type: string,
	transaction_date: string
): TransactionRow {
	return {
		id,
		family_id: 'fam-1',
		transaction_date,
		vendor_name,
		amount,
		credit_card_type,
		excluded: false,
		created_at: `${transaction_date}T10:00:00Z`,
		updated_at: `${transaction_date}T10:00:00Z`
	};
}

/** Apply the predicate to every row and return the matches, like the page does. */
function filter(criteria: Parameters<typeof matchesTransactionFilters>[1]): TransactionRow[] {
	return rows.filter((t) => matchesTransactionFilters(t, criteria));
}

describe('matchesTransactionFilters', () => {
	it('keeps every row when no criteria are set', () => {
		expect(filter({})).toEqual(rows);
	});

	it('filters by credit/bank type', () => {
		const result = filter({ creditCardType: 'PC Financial' });
		expect(result.map((t) => t.vendor_name)).toEqual(['Amazon', 'Safeway']);
	});

	it('treats "all" as no credit/bank-type restriction', () => {
		expect(filter({ creditCardType: 'all' })).toEqual(rows);
	});

	it('returns nothing when no row matches the credit/bank type', () => {
		expect(filter({ creditCardType: 'Simplii Financial' })).toEqual([]);
	});

	it('filters by a case-insensitive vendor substring', () => {
		const result = filter({ vendor: 'safe' });
		expect(result.map((t) => t.vendor_name)).toEqual(['Safeway']);
	});

	it('filters by absolute amount range (rows store expenses as negative)', () => {
		const result = filter({ amountMin: '100', amountMax: '200' });
		expect(result.map((t) => t.vendor_name)).toEqual(['Amazon', 'Costco']);
	});

	it('ignores a blank / non-numeric amount bound', () => {
		expect(filter({ amountMin: '', amountMax: 'abc' })).toEqual(rows);
	});

	it('filters by an inclusive date range', () => {
		const result = filter({ dateFrom: '2025-12-03', dateTo: '2025-12-05' });
		expect(result.map((t) => t.id)).toEqual(['txn-1', 'txn-3']);
	});

	it('combines every filter (only Safeway survives)', () => {
		const result = filter({
