import type { TransactionRow } from '$lib/models/Transaction';
import {
	matchesTransactionFilters,
	hasActiveTransactionFilters
} from './transactionFilters';

/**
 * Real tests for the transactions client-side filter predicate (#{#tcf1a}/#{#tcf2a}).
 *
 * These replace the old `transactions-page-filters.spec.ts`, which re-declared the
 * page's filter logic as local `applyClientFilters` / `hasActiveFilters` copies and
 * asserted against those copies — so the page could break without a failing test.
 * The scenarios below are the same ones that spec pinned, but now exercise the
 * single shared implementation the page actually calls.
 */
const rows: TransactionRow[] = [
	makeRow('txn-1', 'Amazon', -123.45, 'PC Financial', '2025-12-05'),
	makeRow('txn-2', 'Shell Gas', -45.67, 'American Express', '2025-12-04'),
	makeRow('txn-3', 'Safeway', -89.12, 'PC Financial', '2025-12-03'),
	makeRow('txn-4', 'Best Buy', -299.99, 'RBC Financial', '2025-12-02'),
	makeRow('txn-5', 'Costco', -156.78, 'TD Bank', '2025-12-01')
];

function makeRow(
	id: string,
	vendor_name: string,
	amount: number,
	credit_card_type: string,
	transaction_date: string
): TransactionRow {
	return {
		id,
		family_id: 'fam-1',
		transaction_date,
		vendor_name,
		amount,
		credit_card_type,
		excluded: false,
		created_at: `${transaction_date}T10:00:00Z`,
		updated_at: `${transaction_date}T10:00:00Z`
	};
}

/** Apply the predicate to every row and return the matches, like the page does. */
function filter(criteria: Parameters<typeof matchesTransactionFilters>[1]): TransactionRow[] {
	return rows.filter((t) => matchesTransactionFilters(t, criteria));
}

