		expect(hasActiveTransactionFilters({ creditCardType: 'all' })).toBe(false);
	});

	it('is true when the credit/bank-type filter is a concrete type', () => {
		expect(hasActiveTransactionFilters({ creditCardType: 'PC Financial' })).toBe(true);
	});

	it.each([
		['dateFrom', { dateFrom: '2025-12-01' }],
