12	 * single shared implementation the page actually calls.
13	 */
14	const rows: TransactionRow[] = [
15		makeRow('txn-1', 'Amazon', -123.45, 'PC Financial', '2025-12-05'),
16		makeRow('txn-2', 'Shell Gas', -45.67, 'American Express', '2025-12-04'),
17		makeRow('txn-3', 'Safeway', -89.12, 'PC Financial', '2025-12-03'),
18		makeRow('txn-4', 'Best Buy', -299.99, 'RBC Financial', '2025-12-02'),
19		makeRow('txn-5', 'Costco', -156.78, 'TD Bank', '2025-12-01')
20	];
21	
22	function makeRow(
23		id: string,
24		vendor_name: string,
25		amount: number,
26		credit_card_type: string,
27		transaction_date: string
28	): TransactionRow {
29		return {
30			id,
31			family_id: 'fam-1',
32			transaction_date,
33			vendor_name,
34			amount,
35			credit_card_type,
36			excluded: false,
37			created_at: `${transaction_date}T10:00:00Z`,
38			updated_at: `${transaction_date}T10:00:00Z`
39		};
40	}
41	
42	/** Apply the predicate to every row and return the matches, like the page does. */
43	function filter(criteria: Parameters<typeof matchesTransactionFilters>[1]): TransactionRow[] {
44		return rows.filter((t) => matchesTransactionFilters(t, criteria));
45	}
