import { describe, it, expect, vi, beforeEach } from 'vitest';

/**
 * Direct unit tests for getSignedReceiptUrl (the single-path signer).
 *
 * Only the batch variant (collectSignedUrls) was covered before; this pins the
 * single-path contract the receipt viewer and the OCR pipeline depend on:
 *  - empty/missing path → null with no storage round trip;
 *  - storage error → null, swallowed (never throws — a broken thumbnail must not
 *    crash the page or the OCR upload);
 *  - the caller-supplied expiry (300s for the short-lived OCR URL, default 3600s
 *    for display) is forwarded verbatim to createSignedUrl.
 */
const createSignedUrl = vi.fn();
const from = vi.fn(() => ({ createSignedUrl }));

vi.mock('$lib/supabaseClient', () => ({
	supabase: { storage: { from } }
}));

import { getSignedReceiptUrl } from './signedUrl';

describe('getSignedReceiptUrl', () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	it.each([[null], [undefined], ['']])(
		'returns null without calling storage for a %s path',
		async (path) => {
			const result = await getSignedReceiptUrl(path);

			expect(result).toBeNull();
			expect(createSignedUrl).not.toHaveBeenCalled();
		}
	);

	it('returns the signed URL on success', async () => {
		createSignedUrl.mockResolvedValue({ data: { signedUrl: 'https://signed/x.jpg' }, error: null });

		const result = await getSignedReceiptUrl('user-1/x.jpg');

		expect(result).toBe('https://signed/x.jpg');
		expect(from).toHaveBeenCalledWith('receipts');
	});

	it('returns null (does not throw) when storage reports an error', async () => {
		const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
		createSignedUrl.mockResolvedValue({ data: null, error: { message: 'object not found' } });

		const result = await getSignedReceiptUrl('user-1/missing.jpg');

		expect(result).toBeNull();
		consoleError.mockRestore();
	});

	it('forwards the 300s OCR expiry to createSignedUrl', async () => {
		createSignedUrl.mockResolvedValue({ data: { signedUrl: 'https://signed/ocr.jpg' }, error: null });

		await getSignedReceiptUrl('user-1/ocr.jpg', 300);

		expect(createSignedUrl).toHaveBeenCalledWith('user-1/ocr.jpg', 300);
	});

	it('defaults to a 3600s expiry when none is given', async () => {
		createSignedUrl.mockResolvedValue({ data: { signedUrl: 'https://signed/y.jpg' }, error: null });

		await getSignedReceiptUrl('user-1/y.jpg');

		expect(createSignedUrl).toHaveBeenCalledWith('user-1/y.jpg', 3600);
	});
});

