21	type FetchImageFn = (path: string) => Promise<Uint8Array | null>;
22	
23	/**
24	 * #{#cre4b} PDF Export Options
25	 */
26	export interface PDFExportOptions {
27		categories: Category[];
28		dateRange: {
29			start: string;
30			end: string;
31		} | null;
32		onProgress?: ProgressCallback;
33		abortSignal?: AbortSignal;
34		fetchImageFn?: FetchImageFn;
35	}
36	
37	/** Fonts embedded once per document and shared by all drawing helpers */
38	interface PDFFonts {
39		regular: PDFFont;
40		bold: PDFFont;
41	}
42	
43	// #{#cre2a} US Letter page size (612 x 792 points)
44	const PAGE_WIDTH = 612;
45	const PAGE_HEIGHT = 792;
46	const MARGIN = 54; // 0.75 inches
47	const CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN;
48	
49	// Summary table column positions
50	const COL_NUM = MARGIN;
51	const COL_DATE = MARGIN + 30;
52	const COL_VENDOR = MARGIN + 140;
53	const COL_AMOUNT = PAGE_WIDTH - MARGIN - 10;
54	
55	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
56	
57	/**
58	 * Current page and vertical write position for the summary tables. Owns page
59	 * advancement so drawing helpers can only read `page` / move `y` — they never swap
60	 * the page themselves. `ensureRoom()` is the single place a fresh page starts, which
61	 * removes the old temporal coupling (every draw site threading `pdfDoc` and manually
62	 * checking room before writing).
63	 */
64	class PageCursor {
65		page: PDFPage;
66		y: number;
67	
68		private constructor(private readonly pdfDoc: PDFDocument) {
69			this.page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
70			this.y = PAGE_HEIGHT - MARGIN;
71		}
72	
73		/** Begin a fresh page, positioned at its top margin. */
74		static start(pdfDoc: PDFDocument): PageCursor {
75			return new PageCursor(pdfDoc);
76		}
77	
78		/** Start a new page if fewer than `minY` points remain on the current one. */
79		ensureRoom(minY: number): void {
80			if (this.y < minY) {
81				this.page = this.pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
82				this.y = PAGE_HEIGHT - MARGIN;
83			}
84		}
85	}
86	
87	/**
88	 * #{#cre4b} PDFExportService Class
89	 */
90	export class PDFExportService {
91		/**
92		 * #{#cre2b} Criterion 1: Format date as "MMM DD, YYYY"
93		 */
94		formatDate(dateString: string | null | undefined): string {
95			if (!dateString) return 'No Date';
96	
97			try {
98				let year: number, month: number, day: number;
99	
100				if (dateString.includes('T')) {
101					const date = new Date(dateString);
102					year = date.getUTCFullYear();
103					month = date.getUTCMonth();
104					day = date.getUTCDate();
105				} else {
106					const parts = dateString.split('-');
107					year = parseInt(parts[0]);
108					month = parseInt(parts[1]) - 1;
109					day = parseInt(parts[2]);
110				}
111	
112				const dayStr = String(day).padStart(2, '0');
113				return `${MONTHS[month]} ${dayStr}, ${year}`;
114			} catch {
115				return 'No Date';
116			}
117		}
118	
119		/**
120		 * #{#cre2b} Criteria 2, 3, 9: Format amount with $ sign, 2 decimals, comma separators
121		 */
122		formatAmount(amount: number | null | undefined): string {
123			// A receipt whose amount OCR could not read renders as an em-dash rather
124			// than a misleading $0.00. Subtotal/grand-total callers always pass a number.
125			if (amount === null || amount === undefined) return '—';
126			const positive = Math.abs(amount);
127			const fixed = positive.toFixed(2);
128			const [whole, decimal] = fixed.split('.');
129			const withCommas = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
130			return `$${withCommas}.${decimal}`;
131		}
132	
133		/**
134		 * #{#cre2b} Criteria 6, 8: Format vendor name, handle missing
135		 */
136		formatVendorName(name: string | null | undefined): string {
137			if (!name || name.trim() === '') return 'Unknown Vendor';
138			return name.trim();
139		}
140	
141		/**
142		 * #{#cre2a} Criterion 3: Group expenses by category, sort alphabetically, sort by date within
143		 */
144		groupExpensesByCategory(expenses: Expense[]): Record<string, Expense[]> {
145			const groups: Record<string, Expense[]> = {};
146	
147			for (const expense of expenses) {
148				const categoryName = expense.category_name || 'Uncategorized';
149				if (!groups[categoryName]) {
150					groups[categoryName] = [];
151				}
152				groups[categoryName].push(expense);
153			}
154	
155			// Sort within each group by date ascending
156			for (const key of Object.keys(groups)) {
157				groups[key].sort((a, b) => {
158					const dateA = a.transaction_date || '';
159					const dateB = b.transaction_date || '';
160					return dateA.localeCompare(dateB);
161				});
162			}
163	
164			// Return as ordered object (alphabetical keys)
165			const sorted: Record<string, Expense[]> = {};
166			for (const key of Object.keys(groups).sort()) {
167				sorted[key] = groups[key];
168			}
169			return sorted;
170		}
171	
172		/**
173		 * #{#cre2a} Criterion 3: Calculate subtotal for a group of expenses
174		 */
175		calculateSubtotal(expenses: Expense[]): number {
176			return expenses.reduce((sum, e) => sum + Math.abs(e.total_amount ?? 0), 0);
177		}
178	
179		/**
180		 * #{#cre3b} Criteria 2-6: Generate filename based on categories and date range
181		 */
182		generateFilename(
183			categoryNames: string[],
184			dateRange: { start: string; end: string } | null
185		): string {
186			let categoryPart: string;
187			if (categoryNames.length === 1) {
188				categoryPart = categoryNames[0].replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
189			} else {
190				categoryPart = 'multiple_categories';
191			}
192	
193			let datePart: string;
194			if (dateRange) {
195				datePart = `${dateRange.start}_to_${dateRange.end}`;
196			} else {
197				datePart = 'all_time';
198			}
199	
200			return `receipts_${categoryPart}_${datePart}.pdf`;
201		}
202	
203		/**
204		 * #{#cre4b} Criterion 3: Generate the receipt PDF
205		 */
206		async generateReceiptPDF(expenses: Expense[], options: PDFExportOptions): Promise<Uint8Array> {
207			// #{#cre4b} Criterion 10: Check for cancellation
208			this.throwIfAborted(options.abortSignal);
209	
210			const progress = options.onProgress || (() => {});
211			progress('Preparing receipt data...', 0, 1);
212	
213			const pdfDoc = await PDFDocument.create();
214			const fonts: PDFFonts = {
215				regular: await pdfDoc.embedFont(StandardFonts.Helvetica),
216				bold: await pdfDoc.embedFont(StandardFonts.HelveticaBold)
217			};
218	
219			// Group and sort
220			const groups = this.groupExpensesByCategory(expenses);
221	
222			this.drawSummaryPages(pdfDoc, groups, fonts, options);
223			await this.drawReceiptImagePages(pdfDoc, groups, fonts, options, progress);
224	
225			progress('Building PDF...', 1, 1);
226			return await pdfDoc.save();
227		}
228	
229		/**
230		 * #{#cre3b} Criterion 7, 8: Trigger browser download
231		 */
232		downloadPDF(pdfBytes: Uint8Array, filename: string): void {
233			// Copy into a fresh Uint8Array so the backing buffer is a plain ArrayBuffer,
234			// which is what BlobPart requires (pdf-lib bytes are typed over ArrayBufferLike).
235			const blob = new Blob([new Uint8Array(pdfBytes)], { type: 'application/pdf' });
236			const link = document.createElement('a');
237			const url = URL.createObjectURL(blob);
238			link.setAttribute('href', url);
239			link.setAttribute('download', filename);
240			link.style.visibility = 'hidden';
241			document.body.appendChild(link);
242			link.click();
243			document.body.removeChild(link);
244			URL.revokeObjectURL(url);
245		}
246	
247		// ── Private helpers: page layout ─────────────────────────────
248	
249		private throwIfAborted(signal?: AbortSignal): void {
250			if (signal?.aborted) throw new Error('PDF export aborted');
251		}
252	
253		// ── Private helpers: summary table pages ─────────────────────
254	
255		private drawSummaryPages(
256			pdfDoc: PDFDocument,
257			groups: Record<string, Expense[]>,
258			fonts: PDFFonts,
259			options: PDFExportOptions
260		): void {
261			const categoryNames = Object.keys(groups);
262			const cursor = PageCursor.start(pdfDoc);
263	
264			this.drawSummaryHeader(cursor, categoryNames, fonts, options.dateRange);
265	
266			let grandTotal = 0;
267			for (const categoryName of categoryNames) {
268				this.throwIfAborted(options.abortSignal);
269				grandTotal += this.drawCategoryTable(cursor, categoryName, groups[categoryName], fonts);
270			}
271	
272			this.drawGrandTotal(cursor, grandTotal, fonts);
273		}
274	
275		private drawSummaryHeader(
276			cursor: PageCursor,
277			categoryNames: string[],
278			fonts: PDFFonts,
279			dateRange: PDFExportOptions['dateRange']
280		): void {
281			// Title
282			cursor.y = this.drawText(cursor.page, 'Receipt Export', fonts.bold, 18, MARGIN, cursor.y);
283			cursor.y -= 6;
284	
285			// Date range
286			const dateRangeText = dateRange
287				? `${this.formatDate(dateRange.start)} — ${this.formatDate(dateRange.end)}`
288				: 'All Time';
289			cursor.y = this.drawText(cursor.page, dateRangeText, fonts.regular, 10, MARGIN, cursor.y);
290	
291			// Categories
292			const catListText = `Categories: ${categoryNames.join(', ')}`;
293			cursor.y = this.drawWrappedText(
294				cursor.page,
295				catListText,
296				fonts.regular,
297				10,
298				MARGIN,
299				cursor.y,
300				CONTENT_WIDTH
301			);
302	
303			// Generation date
304			const now = new Date();
305			const genDate = `Generated: ${MONTHS[now.getMonth()]} ${String(now.getDate()).padStart(2, '0')}, ${now.getFullYear()}`;
306			cursor.y = this.drawText(cursor.page, genDate, fonts.regular, 10, MARGIN, cursor.y);
307			cursor.y -= 16;
308		}
309	
310		/** Draw one category's heading, rows, and subtotal. Returns the subtotal. */
311		private drawCategoryTable(
312			cursor: PageCursor,
313			categoryName: string,
314			expenses: Expense[],
315			fonts: PDFFonts
316		): number {
317			// Need at least ~100pt for header + 1 row + subtotal
318			cursor.ensureRoom(MARGIN + 100);
319	
320			// Category heading
321			cursor.y = this.drawWrappedText(
322				cursor.page,
323				categoryName,
324				fonts.bold,
325				14,
326				MARGIN,
327				cursor.y,
328				CONTENT_WIDTH
329			);
330			// Separator line
331			cursor.page.drawLine({
332				start: { x: MARGIN, y: cursor.y + 4 },
333				end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 4 },
334				thickness: 1,
335				color: rgb(0.7, 0.7, 0.7)
336			});
337			cursor.y -= 10;
338	
339			// Table header
340			this.drawText(cursor.page, '#', fonts.bold, 9, COL_NUM, cursor.y);
341			this.drawText(cursor.page, 'Date', fonts.bold, 9, COL_DATE, cursor.y);
342			this.drawText(cursor.page, 'Vendor', fonts.bold, 9, COL_VENDOR, cursor.y);
343			this.drawTextRight(cursor.page, 'Amount', fonts.bold, 9, COL_AMOUNT, cursor.y);
344			cursor.y -= 14;
345	
346			// Table rows
347			for (let i = 0; i < expenses.length; i++) {
348				cursor.ensureRoom(MARGIN + 40);
349				this.drawExpenseRow(cursor, expenses[i], i + 1, fonts);
350			}
351	
352			// Subtotal line
353			const subtotal = this.calculateSubtotal(expenses);
354			cursor.page.drawLine({
355				start: { x: COL_VENDOR, y: cursor.y + 12 },
356				end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 12 },
357				thickness: 0.5,
358				color: rgb(0.5, 0.5, 0.5)
359			});
360			this.drawText(cursor.page, 'Subtotal:', fonts.bold, 9, COL_VENDOR, cursor.y);
361			this.drawTextRight(
362				cursor.page,
363				this.formatAmount(subtotal),
364				fonts.bold,
365				9,
366				COL_AMOUNT,
367				cursor.y
368			);
369			cursor.y -= 24;
370	
371			return subtotal;
372		}
373	
374		private drawExpenseRow(
375			cursor: PageCursor,
376			expense: Expense,
377			rowNumber: number,
378			fonts: PDFFonts
379		): void {
380			const vendorMaxWidth = COL_AMOUNT - COL_VENDOR - 60; // leave room for amount
381			const date = this.formatDate(expense.transaction_date);
382			const vendor = this.truncateText(
383				this.formatVendorName(expense.merchant_name),
384				fonts.regular,
385				9,
386				vendorMaxWidth
387			);
388			const amount = this.formatAmount(expense.total_amount);
389	
390			this.drawText(cursor.page, String(rowNumber), fonts.regular, 9, COL_NUM, cursor.y);
391			this.drawText(cursor.page, date, fonts.regular, 9, COL_DATE, cursor.y);
392			this.drawText(cursor.page, vendor, fonts.regular, 9, COL_VENDOR, cursor.y);
393			this.drawTextRight(cursor.page, amount, fonts.regular, 9, COL_AMOUNT, cursor.y);
394			cursor.y -= 14;
395		}
396	
397		private drawGrandTotal(cursor: PageCursor, grandTotal: number, fonts: PDFFonts): void {
398			cursor.ensureRoom(MARGIN + 40);
399			cursor.page.drawLine({
400				start: { x: COL_VENDOR, y: cursor.y + 12 },
401				end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 12 },
402				thickness: 1.5,
403				color: rgb(0, 0, 0)
404			});
405			this.drawText(cursor.page, 'Grand Total:', fonts.bold, 11, COL_VENDOR, cursor.y);
406			this.drawTextRight(
407				cursor.page,
408				this.formatAmount(grandTotal),
409				fonts.bold,
410				11,
411				COL_AMOUNT,
412				cursor.y
413			);
414		}
415	
416		// ── Private helpers: receipt image pages ─────────────────────
417	
418		private async drawReceiptImagePages(
419			pdfDoc: PDFDocument,
420			groups: Record<string, Expense[]>,
421			fonts: PDFFonts,
422			options: PDFExportOptions,
423			progress: ProgressCallback
424		): Promise<void> {
425			const fetchImage: FetchImageFn = options.fetchImageFn || (async () => null);
426			const allExpenses = Object.values(groups).flat();
427			const totalImages = allExpenses.filter((e) => e.receipt_image_path).length || 1;
428			let imageIndex = 0;
429	
430			for (const [categoryName, groupExpenses] of Object.entries(groups)) {
431				this.throwIfAborted(options.abortSignal);
432	
433				for (let i = 0; i < groupExpenses.length; i++) {
434					imageIndex++;
435					progress(`Loading images (${imageIndex} of ${totalImages})...`, imageIndex, totalImages);
436					await this.drawReceiptImagePage(
437						pdfDoc,
438						categoryName,
439						groupExpenses[i],
440						i + 1,
441						fonts,
442						fetchImage
443					);
444				}
445			}
446		}
447	
448		/** One page per receipt: category label, reference header, then the image or a placeholder */
449		private async drawReceiptImagePage(
450			pdfDoc: PDFDocument,
451			categoryName: string,
452			expense: Expense,
453			receiptNumber: number,
454			fonts: PDFFonts,
455			fetchImage: FetchImageFn
456		): Promise<void> {
457			const cursor = PageCursor.start(pdfDoc);
458	
459			// Category label
460			cursor.y = this.drawWrappedText(
461				cursor.page,
462				categoryName,
463				fonts.bold,
464				12,
465				MARGIN,
466				cursor.y,
467				CONTENT_WIDTH
468			);
469	
470			// Receipt reference header
471			const refText = `#${receiptNumber} — ${this.receiptSummaryText(expense)}`;
472			cursor.y = this.drawWrappedText(
473				cursor.page,
474				refText,
475				fonts.regular,
476				10,
477				MARGIN,
478				cursor.y,
479				CONTENT_WIDTH
480			);
481			cursor.y -= 12;
482	
483			if (!expense.receipt_image_path) {
484				this.drawImageUnavailable(cursor, expense, fonts);
485				return;
486			}
487	
488			try {
489				const imageBytes = await fetchImage(expense.receipt_image_path);
490				if (!imageBytes) {
491					this.drawImageUnavailable(cursor, expense, fonts);
492					return;
493				}
494	
495				// Detect image type and embed
496				const image = await this.embedImage(pdfDoc, imageBytes);
497				if (image) {
498					this.drawScaledImage(cursor, image);
499				}
500			} catch {
501				this.drawImageUnavailable(cursor, expense, fonts);
502			}
503		}
504	
505		private receiptSummaryText(expense: Expense): string {
506			return `${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`;
507		}
508	
509		private drawImageUnavailable(cursor: PageCursor, expense: Expense, fonts: PDFFonts): void {
510			cursor.y -= 40;
511			const message = `Receipt image unavailable — ${this.receiptSummaryText(expense)}`;
512			this.drawWrappedText(cursor.page, message, fonts.regular, 11, MARGIN, cursor.y, CONTENT_WIDTH);
513		}
514	
515		/** Scale the image to fit the remaining page area (never upscale) and centre it horizontally */
516		private drawScaledImage(cursor: PageCursor, image: PDFImage): void {
517			const maxHeight = cursor.y - MARGIN;
518			const scale = Math.min(CONTENT_WIDTH / image.width, maxHeight / image.height, 1);
519			const width = image.width * scale;
520			const height = image.height * scale;
521			const x = MARGIN + (CONTENT_WIDTH - width) / 2;
522	
523			cursor.page.drawImage(image, {
524				x,
525				y: cursor.y - height,
526				width,
527				height
528			});
529		}
530	
531		// ── Private helpers: text primitives ─────────────────────────
532	
533		private drawText(
534			page: PDFPage,
535			text: string,
536			font: PDFFont,
537			size: number,
538			x: number,
539			y: number
540		): number {
541			page.drawText(text, { x, y, size, font, color: rgb(0, 0, 0) });
542			return y - size - 2;
543		}
544	
545		private drawWrappedText(
546			page: PDFPage,
547			text: string,
548			font: PDFFont,
549			size: number,
550			x: number,
551			y: number,
552			maxWidth: number
553		): number {
554			const words = text.split(' ');
555			let line = '';
556			const lineHeight = size + 2;
557	
558			for (const word of words) {
559				const testLine = line ? `${line} ${word}` : word;
560				const testWidth = font.widthOfTextAtSize(testLine, size);
561				if (testWidth > maxWidth && line) {
562					page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
563					y -= lineHeight;
564					line = word;
565				} else {
566					line = testLine;
567				}
568			}
569			if (line) {
570				page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
571				y -= lineHeight;
572			}
573			return y;
574		}
575	
576		private drawTextRight(
577			page: PDFPage,
578			text: string,
579			font: PDFFont,
580			size: number,
581			rightX: number,
582			y: number
583		): number {
584			const width = font.widthOfTextAtSize(text, size);
585			page.drawText(text, { x: rightX - width, y, size, font, color: rgb(0, 0, 0) });
586			return y - size - 2;
587		}
588	
589		private truncateText(text: string, font: PDFFont, size: number, maxWidth: number): string {
590			if (font.widthOfTextAtSize(text, size) <= maxWidth) return text;
591			const ellipsis = '...';
592			let truncated = text;
593			while (truncated.length > 0 && font.widthOfTextAtSize(truncated + ellipsis, size) > maxWidth) {
594				truncated = truncated.slice(0, -1);
595			}
596			return truncated + ellipsis;
597		}
598	
599		private async embedImage(pdfDoc: PDFDocument, imageBytes: Uint8Array): Promise<PDFImage | null> {
600			// Try JPEG first, then PNG
601			try {
602				return await pdfDoc.embedJpg(imageBytes);
603			} catch {
604				try {
605					return await pdfDoc.embedPng(imageBytes);
606				} catch {
607					return null;
608				}
609			}
610		}
611	}
