/**
 * PDFExportService Unit Tests
 *
 * Tests for PDF export functionality — category receipt export with grouped tables and images
 * Specification: specs/specifications/category-receipt-pdf-export.md
 *
 * Traceable to:
 * - #{#cre5a} - PDF Export Unit Tests
 * - #{#cre2a} - PDF Document Structure
 * - #{#cre2b} - PDF Data Formatting
 * - #{#cre3a} - Receipt Image Handling
 * - #{#cre3b} - PDF File Download Mechanism
 * - #{#cre4b} - PDF Export Service Implementation
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { PDFExportService } from './PDFExportService';
import type { Expense } from './ExpenseService';
import { makeExpense } from '$lib/tests/builders/rowBuilders';

// ── Tests ────────────────────────────────────────────────────────────

describe('PDFExportService', () => {
	let service: PDFExportService;

	beforeEach(() => {
		service = new PDFExportService();
	});

	// ── #{#cre2b} Date Formatting ──────────────────────────────────

	describe('formatDate', () => {
		it('should format dates as "MMM DD, YYYY" (e.g., "Jan 05, 2026")', () => {
			// #{#cre2b} Criterion 1 / #{#cre5a} Test 9
			const result = service.formatDate('2026-01-05');
			expect(result).toBe('Jan 05, 2026');
		});

		it('should format dates with ISO timestamp correctly', () => {
			// #{#cre2b} Criterion 1
			const result = service.formatDate('2026-12-25T08:30:00Z');
			expect(result).toBe('Dec 25, 2026');
		});

		it('should return "No Date" for missing dates', () => {
			// #{#cre2b} Criterion 10
			expect(service.formatDate('')).toBe('No Date');
			expect(service.formatDate(null)).toBe('No Date');
			expect(service.formatDate(undefined)).toBe('No Date');
		});

		it('should handle all 12 months correctly', () => {
			// #{#cre2b} Criterion 1
			const months = [
				['2026-01-15', 'Jan 15, 2026'],
				['2026-02-15', 'Feb 15, 2026'],
				['2026-03-15', 'Mar 15, 2026'],
				['2026-04-15', 'Apr 15, 2026'],
				['2026-05-15', 'May 15, 2026'],
				['2026-06-15', 'Jun 15, 2026'],
				['2026-07-15', 'Jul 15, 2026'],
				['2026-08-15', 'Aug 15, 2026'],
				['2026-09-15', 'Sep 15, 2026'],
				['2026-10-15', 'Oct 15, 2026'],
				['2026-11-15', 'Nov 15, 2026'],
				['2026-12-15', 'Dec 15, 2026']
			];
			for (const [input, expected] of months) {
				expect(service.formatDate(input)).toBe(expected);
			}
		});
	});

	// ── #{#cre2b} Amount Formatting ────────────────────────────────

	describe('formatAmount', () => {
		it('should format amounts with dollar sign and 2 decimals', () => {
			// #{#cre2b} Criterion 2 / #{#cre5a} Test 8
			expect(service.formatAmount(125.99)).toBe('$125.99');
		});

		it('should use comma separators for thousands', () => {
			// #{#cre2b} Criterion 3
			expect(service.formatAmount(1234.56)).toBe('$1,234.56');
			expect(service.formatAmount(1000000)).toBe('$1,000,000.00');
		});

		it('should convert negative amounts to positive', () => {
			// #{#cre2b} Criterion 2
			expect(service.formatAmount(-25.5)).toBe('$25.50');
		});

		it('should format an explicit zero amount as $0.00', () => {
			// #{#cre2b} Criterion 9 — a real zero is distinct from a missing amount
			expect(service.formatAmount(0)).toBe('$0.00');
		});

		it('should render a missing (null/undefined) amount as an em-dash, not $0.00', () => {
			// A receipt whose amount OCR could not read must not export as a
			// misleading $0.00 — it is flagged as unknown.
			expect(service.formatAmount(null)).toBe('—');
			expect(service.formatAmount(undefined)).toBe('—');
		});

		it('should round to 2 decimal places', () => {
			// #{#cre2b} Criterion 2
			// Note: JS toFixed() uses banker's rounding — 5.755 → '5.75' in V8
			expect(service.formatAmount(5.756)).toBe('$5.76');
			expect(service.formatAmount(10.999)).toBe('$11.00');
		});
	});

	// ── #{#cre2a} Category Grouping and Sorting ────────────────────

	describe('groupExpensesByCategory', () => {
		it('should group expenses by category_name', () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 4
			const expenses: Expense[] = [
				makeExpense({ receipt_id: 'r1', category_name: 'Office Supplies', total_amount: 50 }),
				makeExpense({ receipt_id: 'r2', category_name: 'Repairs', total_amount: 100 }),
				makeExpense({ receipt_id: 'r3', category_name: 'Office Supplies', total_amount: 75 })
			];

			const groups = service.groupExpensesByCategory(expenses);
			expect(Object.keys(groups)).toHaveLength(2);
			expect(groups['Office Supplies']).toHaveLength(2);
			expect(groups['Repairs']).toHaveLength(1);
		});

		it('should sort groups alphabetically by category name', () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 10
			const expenses: Expense[] = [
				makeExpense({ receipt_id: 'r1', category_name: 'Repairs' }),
				makeExpense({ receipt_id: 'r2', category_name: 'Auto' }),
				makeExpense({ receipt_id: 'r3', category_name: 'Office Supplies' })
			];

			const groups = service.groupExpensesByCategory(expenses);
			const categoryNames = Object.keys(groups);
			expect(categoryNames).toEqual(['Auto', 'Office Supplies', 'Repairs']);
		});

		it('should sort expenses within each group by date ascending (oldest first)', () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 10
			const expenses: Expense[] = [
				makeExpense({
					receipt_id: 'r1',
					category_name: 'Office Supplies',
					transaction_date: '2026-03-15'
				}),
				makeExpense({
					receipt_id: 'r2',
					category_name: 'Office Supplies',
					transaction_date: '2026-01-05'
				}),
				makeExpense({
					receipt_id: 'r3',
					category_name: 'Office Supplies',
					transaction_date: '2026-02-10'
				})
			];

			const groups = service.groupExpensesByCategory(expenses);
			const dates = groups['Office Supplies'].map((e) => e.transaction_date);
			expect(dates).toEqual(['2026-01-05', '2026-02-10', '2026-03-15']);
		});

		it('should handle expenses with null category_name', () => {
			// #{#cre2b} Criterion 8
			const expenses: Expense[] = [
				makeExpense({ receipt_id: 'r1', category_name: null }),
				makeExpense({ receipt_id: 'r2', category_name: 'Office Supplies' })
			];

			const groups = service.groupExpensesByCategory(expenses);
			expect(groups['Uncategorized']).toHaveLength(1);
			expect(groups['Office Supplies']).toHaveLength(1);
		});
	});

	// ── #{#cre2a} Subtotal and Grand Total ─────────────────────────

	describe('calculateSubtotal', () => {
		it('should calculate the sum of amounts for a list of expenses', () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 6
			const expenses: Expense[] = [
				makeExpense({ total_amount: 125.99 }),
				makeExpense({ total_amount: 45.5 }),
				makeExpense({ total_amount: 312.0 })
			];

			expect(service.calculateSubtotal(expenses)).toBeCloseTo(483.49, 2);
		});

		it('should return 0 for an empty list', () => {
			// #{#cre5a} Test 1
			expect(service.calculateSubtotal([])).toBe(0);
		});

		it('should use absolute values (negative amounts treated as positive)', () => {
			// #{#cre2b} Criterion 2
			const expenses: Expense[] = [
				makeExpense({ total_amount: -25.5 }),
				makeExpense({ total_amount: 100 })
			];

			expect(service.calculateSubtotal(expenses)).toBeCloseTo(125.5, 2);
		});
	});

	// ── #{#cre3b} Filename Generation ──────────────────────────────

	describe('generateFilename', () => {
		it('should generate filename for single category with date range', () => {
			// #{#cre3b} Criterion 3 / #{#cre5a} Test 12
			const filename = service.generateFilename(['Office Supplies'], {
				start: '2026-01-01',
				end: '2026-12-31'
			});
			expect(filename).toBe('receipts_Office_Supplies_2026-01-01_to_2026-12-31.pdf');
		});

		it('should generate filename for multiple categories with date range', () => {
			// #{#cre3b} Criterion 4 / #{#cre5a} Test 12
			const filename = service.generateFilename(['Office Supplies', 'Repairs'], {
				start: '2026-01-01',
				end: '2026-12-31'
			});
			expect(filename).toBe('receipts_multiple_categories_2026-01-01_to_2026-12-31.pdf');
		});

		it('should generate filename for all time (no date range)', () => {
			// #{#cre3b} Criterion 5 / #{#cre5a} Test 12
			const filename = service.generateFilename(['Office Supplies'], null);
			expect(filename).toBe('receipts_Office_Supplies_all_time.pdf');
		});

		it('should sanitize category names in filename', () => {
			// #{#cre3b} Criterion 6
			const filename = service.generateFilename(['Coffee & Tea'], null);
			expect(filename).toBe('receipts_Coffee__Tea_all_time.pdf');
			expect(filename).not.toContain('&');
		});

		it('should replace spaces with underscores in filename', () => {
			// #{#cre3b} Criterion 6
			const filename = service.generateFilename(['Office Supplies'], null);
			expect(filename).not.toMatch(/receipts_Office Supplies/);
			expect(filename).toContain('Office_Supplies');
		});
	});

	// ── #{#cre2b} Vendor Name Handling ─────────────────────────────

	describe('formatVendorName', () => {
		it('should preserve original casing and characters', () => {
			// #{#cre2b} Criterion 6
			expect(service.formatVendorName('Café François')).toBe('Café François');
		});

		it('should return "Unknown Vendor" for missing vendor names', () => {
			// #{#cre2b} Criterion 8
			expect(service.formatVendorName(null)).toBe('Unknown Vendor');
			expect(service.formatVendorName('')).toBe('Unknown Vendor');
			expect(service.formatVendorName(undefined)).toBe('Unknown Vendor');
		});

		it('should trim whitespace from vendor names', () => {
			// #{#cre2b} Criterion 6
			expect(service.formatVendorName('  Starbucks  ')).toBe('Starbucks');
		});
	});

	// ── #{#cre4b} PDF Generation (integration with pdf-lib) ───────

	describe('generateReceiptPDF', () => {
		it('should return a Uint8Array (valid PDF bytes)', async () => {
			// #{#cre4b} Criterion 3 / #{#cre5a} Test 2
			const expenses: Expense[] = [makeExpense()];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: { start: '2026-01-01', end: '2026-12-31' }
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should start with PDF magic bytes (%PDF)', async () => {
			// #{#cre2a} Criterion 6 / #{#cre5a} Test 2
			const expenses: Expense[] = [makeExpense()];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: { start: '2026-01-01', end: '2026-12-31' }
			});
			// PDF files start with %PDF
			const header = String.fromCharCode(result[0], result[1], result[2], result[3]);
			expect(header).toBe('%PDF');
		});

		it('should generate PDF with multiple categories grouped separately', async () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 4
			const expenses: Expense[] = [
				makeExpense({
					receipt_id: 'r1',
					category_name: 'Office Supplies',
					merchant_name: 'Staples',
					total_amount: 45.5,
					receipt_image_path: undefined
				}),
				makeExpense({
					receipt_id: 'r2',
					category_name: 'Repairs',
					merchant_name: 'Home Hardware',
					total_amount: 312.0,
					receipt_image_path: undefined
				})
			];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [
					{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' },
					{ id: 'cat2', family_id: 'f1', name: 'Repairs', color: '#00FF00' }
				],
				dateRange: null
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should call onProgress callback during generation', async () => {
			// #{#cre4b} Criterion 9 / #{#cre5a} Test 15
			const progressCalls: { step: string; current: number; total: number }[] = [];
			const expenses: Expense[] = [makeExpense({ receipt_image_path: undefined })];
			await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				onProgress: (step: string, current: number, total: number) => {
					progressCalls.push({ step, current, total });
				}
			});
			expect(progressCalls.length).toBeGreaterThan(0);
			// Should have at least a "Preparing" and "Building PDF" step
			expect(progressCalls.some((c) => c.step.toLowerCase().includes('prepar'))).toBe(true);
		});

		it('should call fetchImageFn for each expense with a receipt_image_path', async () => {
			// #{#cre3a} Criterion 1 / #{#cre5a} Test 3
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockResolvedValue(null);
			const expenses: Expense[] = [
				makeExpense({ receipt_id: 'r1', receipt_image_path: 'user1/img1.jpg' }),
				makeExpense({ receipt_id: 'r2', receipt_image_path: 'user1/img2.jpg' }),
				makeExpense({ receipt_id: 'r3', receipt_image_path: undefined })
			];
			await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			// Should be called for the 2 expenses with images, not the one without
			expect(fetchImageFn).toHaveBeenCalledTimes(2);
			expect(fetchImageFn).toHaveBeenCalledWith('user1/img1.jpg');
			expect(fetchImageFn).toHaveBeenCalledWith('user1/img2.jpg');
		});

		it('should still produce valid PDF when image fetch fails', async () => {
			// #{#cre3a} Criterion 9 / #{#cre5a} Test 13
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockRejectedValue(new Error('Network error'));
			const expenses: Expense[] = [makeExpense({ receipt_image_path: 'user1/broken.jpg' })];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			// PDF should still be valid despite fetch failure
			expect(result).toBeInstanceOf(Uint8Array);
			const header = String.fromCharCode(result[0], result[1], result[2], result[3]);
			expect(header).toBe('%PDF');
		});

		it('should still produce valid PDF when fetchImageFn returns null', async () => {
			// #{#cre3a} Criterion 9 / #{#cre5a} Test 5
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockResolvedValue(null);
			const expenses: Expense[] = [makeExpense({ receipt_image_path: 'user1/missing.jpg' })];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should support cancellation via AbortSignal', async () => {
			// #{#cre4b} Criterion 10 / #{#cre5a} Test 14
			const controller = new AbortController();
			controller.abort(); // Abort immediately

			const expenses: Expense[] = [makeExpense({ receipt_image_path: undefined })];
			await expect(
				service.generateReceiptPDF(expenses, {
					categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
					dateRange: null,
					abortSignal: controller.signal
				})
			).rejects.toThrow(/abort|cancel/i);
		});
	});

	// #{#cre1a} #{#cre1b} Button enable/disable logic moved to
	// $lib/utils/pdfExportState (RF-13) — see pdfExportState.spec.ts.
});

