/**
 * CSVExportService Unit Tests
 *
 * Tests for CSV export functionality
 * Specification: specs/specifications/expense-csv-export.md
 *
 * Traceable to:
 * - #{#exp5a} - CSV Export Unit Tests (IMPLEMENTED)
 */

import { describe, it, expect } from 'vitest';
import { CSVExportService } from './CSVExportService';
import type { Expense } from './ExpenseService';
import { makeExpense } from '$lib/tests/builders/rowBuilders';

describe('CSVExportService', () => {
	describe('exportExpensesToCSV', () => {
		it('should generate CSV with headers only for empty array', () => {
			// #{#exp5a} Test 1
			const service = new CSVExportService();
			const csv = service.exportExpensesToCSV([]);
			expect(csv).toBe('Date,Merchant Name,Amount,Category');
		});

		it('should throw error for null expenses array', () => {
			// #{#exp4a} Criterion 2
			const service = new CSVExportService();
			expect(() => service.exportExpensesToCSV(null as unknown as Expense[])).toThrow(
				'Expenses array is required'
			);
		});

		it('should throw error for undefined expenses array', () => {
			// #{#exp4a} Criterion 2
			const service = new CSVExportService();
			expect(() => service.exportExpensesToCSV(undefined as unknown as Expense[])).toThrow(
				'Expenses array is required'
			);
		});

		it('should generate CSV with correct data for single expense', () => {
			// #{#exp5a} Test 2
			const service = new CSVExportService();
			const expenses = [
				makeExpense({
					transaction_date: '2025-01-15', // Use date-only format to avoid timezone issues
					merchant_name: 'Starbucks',
					total_amount: 5.75,
					category_name: 'Coffee'
				})
			];

			const csv = service.exportExpensesToCSV(expenses);
			const lines = csv.split('\n');

			expect(lines).toHaveLength(2);
			expect(lines[0]).toBe('Date,Merchant Name,Amount,Category');
			expect(lines[1]).toBe('2025-01-15,Starbucks,5.75,Coffee');
		});

		it('should generate CSV with multiple rows for multiple expenses', () => {
			// #{#exp5a} Test 3
			const service = new CSVExportService();
			const expenses = [
				makeExpense({
					receipt_id: '1',
					transaction_date: '2025-01-15',
					merchant_name: 'Starbucks',
					total_amount: 5.75,
					category_name: 'Coffee'
				}),
				makeExpense({
					receipt_id: '2',
					transaction_date: '2025-01-14',
					merchant_name: 'Shell',
					total_amount: 45.0,
					category_name: 'Gas'
				})
			];

			const csv = service.exportExpensesToCSV(expenses);
			const lines = csv.split('\n');

			expect(lines).toHaveLength(3);
			expect(lines[1]).toBe('2025-01-15,Starbucks,5.75,Coffee');
			expect(lines[2]).toBe('2025-01-14,Shell,45.00,Gas');
		});

		it('should properly quote merchant names containing commas', () => {
			// #{#exp5a} Test 4
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: 'Acme, Inc.' })];

			const csv = service.exportExpensesToCSV(expenses);
			expect(csv).toContain('"Acme, Inc."');
		});

		it('should properly escape merchant names containing quotes', () => {
			// #{#exp5a} Test 5
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: 'Joe\'s "Best" Cafe' })];

			const csv = service.exportExpensesToCSV(expenses);
			// Quotes should be escaped as double-quotes and field should be quoted
			expect(csv).toContain('"Joe\'s ""Best"" Cafe"');
		});

		it('should convert negative amounts to positive', () => {
			// #{#exp5a} Test 6
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: 'Refund Store', total_amount: -25.5 })];

			const csv = service.exportExpensesToCSV(expenses);
			expect(csv).toContain('25.50'); // Positive and 2 decimals
		});

		it('should export a missing (null) amount as a blank field, not 0.00', () => {
			// A receipt whose amount OCR could not read must not export as a
			// misleading 0.00 — the amount column is left empty.
			const service = new CSVExportService();
			const expenses = [
				makeExpense({
					transaction_date: '2025-01-15',
					merchant_name: 'Amountless Store',
					total_amount: null,
					category_name: 'Groceries'
				})
			];

			const csv = service.exportExpensesToCSV(expenses);
			// Row shape is date,merchant,amount,category → the amount field is empty
			expect(csv).toContain('2025-01-15,Amountless Store,,Groceries');
			expect(csv).not.toContain('0.00');
		});

		it('should round amounts to 2 decimal places', () => {
			// #{#exp5a} Test 7
			const service = new CSVExportService();
			const expenses = [
				makeExpense({ receipt_id: '1', merchant_name: 'Test', total_amount: 5.755 }),
				makeExpense({ receipt_id: '2', merchant_name: 'Test2', total_amount: 10.999 })
			];

			const csv = service.exportExpensesToCSV(expenses);
			// JavaScript's toFixed() uses banker's rounding (round half to even)
			// 5.755 rounds to 5.76 (rounds up because odd)
			// But toFixed actually rounds 5.755 to 5.75 in some JS engines
			// Let's just verify 2 decimal places
			expect(csv).toMatch(/Test,5\.\d{2},/); // 2 decimal places
			expect(csv).toMatch(/Test2,11\.00,/); // Rounded up to 11.00
		});

		it('should handle missing category gracefully', () => {
			// #{#exp5a} Test 8
			const service = new CSVExportService();
			const expenses = [
				makeExpense({
					transaction_date: '2025-01-15',
					merchant_name: 'Uncategorized Store',
					total_amount: 50.0,
					category_name: null
				})
			];

			const csv = service.exportExpensesToCSV(expenses);
			const lines = csv.split('\n');
			expect(lines[1]).toBe('2025-01-15,Uncategorized Store,50.00,');
		});

		it('should format all dates in YYYY-MM-DD format', () => {
			// #{#exp5a} Test 9
			const service = new CSVExportService();
			const expenses = [
				makeExpense({
					receipt_id: '1',
					transaction_date: '2025-01-05T08:30:00Z',
					merchant_name: 'Test'
				}),
				makeExpense({ receipt_id: '2', transaction_date: '2025-12-25', merchant_name: 'Test2' })
			];

			const csv = service.exportExpensesToCSV(expenses);
			expect(csv).toContain('2025-01-05,Test');
			expect(csv).toContain('2025-12-25,Test2');
		});

		it('should preserve UTF-8 characters correctly', () => {
			// #{#exp5a} Test 10
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: 'Café François', category_name: 'Déjeuner' })];

			const csv = service.exportExpensesToCSV(expenses);
			expect(csv).toContain('Café François');
			expect(csv).toContain('Déjeuner');
		});

		it('should handle large exports with 1000+ expenses', () => {
			// #{#exp5a} Test 12
			const service = new CSVExportService();
			const expenses: Expense[] = [];

			// Generate 1000 expenses
			for (let i = 0; i < 1000; i++) {
				expenses.push(
					makeExpense({
						receipt_id: `${i}`,
						merchant_name: `Merchant ${i}`,
						total_amount: i * 10.5,
						category_name: 'Category'
					})
				);
			}

			const csv = service.exportExpensesToCSV(expenses);
			const lines = csv.split('\n');

			// Header + 1000 rows
			expect(lines).toHaveLength(1001);
			expect(lines[0]).toBe('Date,Merchant Name,Amount,Category');
		});

		it('should trim whitespace from merchant names', () => {
			// #{#exp2b} Criterion 2
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: '  Starbucks  ', total_amount: 5.0 })];

			const csv = service.exportExpensesToCSV(expenses);
			expect(csv).toContain('Starbucks,5.00'); // No extra spaces
		});

		it('should handle merchant names with newlines', () => {
			// Edge case: newlines in merchant names
			const service = new CSVExportService();
			const expenses = [makeExpense({ merchant_name: 'Multi\nLine\nMerchant' })];

			const csv = service.exportExpensesToCSV(expenses);
			// Should be quoted because it contains newlines
			expect(csv).toContain('"Multi\nLine\nMerchant"');
		});
	});

	describe('generateFilename', () => {
		it('should generate filename for all time filter', () => {
			// #{#exp5a} Test 11
			const service = new CSVExportService();
			const filename = service.generateFilename('all');
			expect(filename).toBe('expenses_all_time.csv');
		});

		it('should generate filename for last 30 days filter', () => {
			// #{#exp5a} Test 11
			const service = new CSVExportService();
			const filename = service.generateFilename('last_30');
			expect(filename).toBe('expenses_last_30_days.csv');
		});

		it('should generate filename for last 90 days filter', () => {
			// #{#exp5a} Test 11
			const service = new CSVExportService();
			const filename = service.generateFilename('last_90');
			expect(filename).toBe('expenses_last_90_days.csv');
		});

		it('should generate filename for custom date range', () => {
			// #{#exp5a} Test 11
			const service = new CSVExportService();
			// Use string dates to avoid timezone conversion issues
			const filename = service.generateFilename('custom', '2025-01-01', '2025-01-31');
			expect(filename).toBe('expenses_2025-01-01_to_2025-01-31.csv');
		});

		it('should generate filename for single day', () => {
			// #{#exp3a} Special case
			const service = new CSVExportService();
			// Use string date to avoid timezone conversion issues
			const filename = service.generateFilename('custom', '2025-01-15', '2025-01-15');
			expect(filename).toBe('expenses_2025-01-15.csv');
		});

		it('should generate fallback filename for custom without dates', () => {
			const service = new CSVExportService();
			const filename = service.generateFilename('custom');
			expect(filename).toBe('expenses_custom.csv');
		});

		it('should handle string dates for custom range', () => {
			const service = new CSVExportService();
			const filename = service.generateFilename('custom', '2025-02-01', '2025-02-28');
			expect(filename).toBe('expenses_2025-02-01_to_2025-02-28.csv');
		});
	});

	// downloadCSV uses the DOM (Blob + <a download> click); it's covered by real
	// browser tests in CSVExportService.svelte.spec.ts (the `client` project).
});

