import { describe, it, expect } from 'vitest';
import { getDuplicateInfo, isDuplicate } from './duplicateHelpers';
import type { ReceiptRow } from '$lib/models/Receipt';

/**
 * Test suite for duplicate detection UI helpers
 *
 * Specifications covered:
 * - #{#dup1a} Visual duplicate highlighting - helper functions
 * - #{#dup2a} Duplicate count display - count calculation
 * - #{#dup2b} Filter interaction with duplicates
 */

describe('#{#dup1a} isDuplicate helper', () => {
	function createReceipt(id: string, amount: number | null, date: string | null): ReceiptRow {
		return {
			id,
			user_id: 'test-user',
			total_amount: amount,
			transaction_date: date,
			merchant_name: `Merchant ${id}`,
			receipt_image_path: null,
			tax: null,
			currency: 'USD',
			credit_card_name: null,
			credit_card_last_4: null,
			created_at: new Date().toISOString()
		} as ReceiptRow;
	}

	it('should return true for receipt in duplicate group', () => {
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2']]]);

		const result = isDuplicate('r1', duplicateGroups);

		expect(result).toBe(true);
	});

	it('should return false for receipt not in any duplicate group', () => {
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2']]]);

		const result = isDuplicate('r3', duplicateGroups);

		expect(result).toBe(false);
	});

	it('should return false when duplicateGroups is empty', () => {
		const duplicateGroups = new Map();

		const result = isDuplicate('r1', duplicateGroups);

		expect(result).toBe(false);
	});
});

describe('#{#dup2a} getDuplicateInfo helper', () => {
	it('should return duplicate count for receipt in group', () => {
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2', 'r3']]]);

		const result = getDuplicateInfo('r1', duplicateGroups);

		expect(result).toEqual({
			isDuplicate: true,
			count: 3
		});
	});

	it('should return no duplicate info for unique receipt', () => {
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2']]]);

		const result = getDuplicateInfo('r3', duplicateGroups);

		expect(result).toEqual({
			isDuplicate: false,
			count: 0
		});
	});

	it('should handle multiple duplicate groups correctly', () => {
		const duplicateGroups = new Map([
			['50|2025-01-15', ['r1', 'r2']],
			['75|2025-01-20', ['r3', 'r4', 'r5']]
		]);

		const result1 = getDuplicateInfo('r1', duplicateGroups);
		const result2 = getDuplicateInfo('r4', duplicateGroups);

		expect(result1).toEqual({ isDuplicate: true, count: 2 });
		expect(result2).toEqual({ isDuplicate: true, count: 3 });
	});

	it('should return count of 2 for pair duplicates', () => {
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2']]]);

		const result = getDuplicateInfo('r2', duplicateGroups);

		expect(result).toEqual({
			isDuplicate: true,
			count: 2
		});
	});
});

describe('#{#dup2b} Filter interaction - duplicate detection on filtered list', () => {
	it('should detect duplicates only in provided receipt list', () => {
		// This test verifies that duplicate detection works on any subset of receipts
		// simulating filtered results
		const filteredReceipts = [
			{ id: 'r1', total_amount: 50, transaction_date: '2025-01-15' },
			{ id: 'r2', total_amount: 50, transaction_date: '2025-01-15' }
		] as ReceiptRow[];

		// In actual implementation, detectDuplicates is called on filtered receipts
		// This test verifies the helper functions work with any receipt subset
		const duplicateGroups = new Map([['50|2025-01-15', ['r1', 'r2']]]);

		expect(isDuplicate('r1', duplicateGroups)).toBe(true);
		expect(isDuplicate('r2', duplicateGroups)).toBe(true);
	});
});

