import { fileTypeFromBuffer } from 'file-type';

export type FileCategory = 'pdf' | 'image';

export interface FileValidationResult {
	isValid: boolean;
	mimeType?: string;
	category?: FileCategory;
	error?: string;
}

export class FileValidator {
	private static readonly MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

	private static readonly SUPPORTED_TYPES = {
		PDF: ['application/pdf'],
		IMAGE: ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic', 'image/heif']
	} as const;

	/**
	 * Validates a file buffer by checking its magic numbers (file signature)
	 * This prevents users from simply renaming files to bypass validation
	 */
	static async validateFile(buffer: Buffer, _fileName?: string): Promise<FileValidationResult> {
		// Check file size
		if (buffer.length > this.MAX_FILE_SIZE) {
			return {
				isValid: false,
				error: `File size exceeds ${this.MAX_FILE_SIZE / 1024 / 1024}MB limit`
			};
		}

		// Detect actual file type from magic numbers
		const detectedType = await fileTypeFromBuffer(buffer);

		if (!detectedType) {
			return {
				isValid: false,
				error: 'Could not determine file type. The file may be corrupted or unsupported.'
			};
		}

		// Validate against whitelist
		const category = this.categorizeMimeType(detectedType.mime);

		if (!category) {
			const supported = [...this.SUPPORTED_TYPES.PDF, ...this.SUPPORTED_TYPES.IMAGE].join(', ');

			return {
				isValid: false,
				error: `File type ${detectedType.mime} is not supported. Supported types: ${supported}`
			};
		}

		return {
			isValid: true,
			mimeType: detectedType.mime,
			category
		};
	}

	/**
	 * Categorizes a MIME type into pdf or image
	 */
	private static categorizeMimeType(mimeType: string): FileCategory | null {
		const normalized = mimeType.toLowerCase();

		if ((this.SUPPORTED_TYPES.PDF as readonly string[]).includes(normalized)) {
			return 'pdf';
		}

		if ((this.SUPPORTED_TYPES.IMAGE as readonly string[]).includes(normalized)) {
			return 'image';
		}

		return null;
	}

	/**
	 * Get list of supported MIME types
	 */
	static getSupportedTypes(): string[] {
		return [...this.SUPPORTED_TYPES.PDF, ...this.SUPPORTED_TYPES.IMAGE];
	}
}

