import { OcrService } from '$lib/services/OcrService';
import { FileValidator } from './fileValidation';
import { sanitizeExtract, type ReceiptExtract } from '$lib/utils/sanitize';

/**
 * Server-side OCR processor
 * This module should only be imported in server-side code (+server.ts, +page.server.ts, etc.)
 */

export interface OcrProcessingResult {
	success: boolean;
	data?: ReceiptExtract;
	error?: string;
	mimeType?: string;
	category?: 'pdf' | 'image';
}

/**
 * Process a file buffer and extract receipt data using OCR
 *
 * @param buffer - File buffer to validate
 * @param fileUrl - Public URL of the uploaded file
 * @param fileName - Original file name (for logging)
 * @returns OCR processing result
 */
export async function processOcrFromBuffer(
	buffer: Buffer,
	fileUrl: string,
	fileName?: string
): Promise<OcrProcessingResult> {
	try {
		// Validate file using magic number detection
		const validation = await FileValidator.validateFile(buffer, fileName);

		if (!validation.isValid) {
			return {
				success: false,
				error: validation.error || 'File validation failed'
			};
		}

		const mimeType = validation.mimeType!;
		const category = validation.category!;

		// Process with OCR
		const ocrService = new OcrService();
		const data = sanitizeExtract(await ocrService.extractFromUrl(fileUrl, mimeType));

		return {
			success: true,
			data,
			mimeType,
			category
		};
	} catch (err) {
		const message = err instanceof Error ? err.message : 'Unknown error occurred';
		console.error('OCR processing error:', message, err);

		return {
			success: false,
			error: `OCR processing failed: ${message}`
		};
	}
}

/**
 * Process OCR from a public URL (when file is already uploaded to storage)
 * This skips the buffer validation since the file is already in storage
 *
 * @param fileUrl - Public URL of the file
 * @param mimeType - MIME type of the file (from upload metadata)
 * @returns OCR processing result
 */
export async function processOcrFromUrl(
	fileUrl: string,
	mimeType: string
): Promise<OcrProcessingResult> {
	try {
		const ocrService = new OcrService();
		const data = sanitizeExtract(await ocrService.extractFromUrl(fileUrl, mimeType));

		return {
			success: true,
			data,
			mimeType
		};
	} catch (err) {
		const message = err instanceof Error ? err.message : 'Unknown error occurred';
		console.error('OCR processing error:', message, err);

		return {
			success: false,
			error: `OCR processing failed: ${message}`
		};
	}
}

