import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { OcrService } from '$lib/services/OcrService';
import { FileValidator } from '$lib/server/fileValidation';

/**
 * POST /api/ocr
 *
 * Processes a file upload and extracts receipt data using OCR
 *
 * Request body (multipart/form-data):
 * - file: The image or PDF file to process
 *
 * Response:
 * - 200: { mimeType: string, category: 'pdf' | 'image', ocrData: ReceiptExtract }
 * - 400: Validation error
 * - 500: Processing error
 */
export const POST: RequestHandler = async ({ request }) => {
	try {
		// Parse form data
		const formData = await request.formData();
		const file = formData.get('file') as File;

		if (!file) {
			throw error(400, 'No file uploaded. Please provide a file in the request.');
		}

		// Convert file to buffer for validation
		const arrayBuffer = await file.arrayBuffer();
		const buffer = Buffer.from(arrayBuffer);

		// Validate file using magic number detection
		const validation = await FileValidator.validateFile(buffer, file.name);

		if (!validation.isValid) {
			throw error(400, validation.error || 'File validation failed');
		}

		// At this point, validation.mimeType and validation.category are guaranteed to exist
		const mimeType = validation.mimeType!;
		const category = validation.category!;

		// Get file URL - in production, this should be a temporary signed URL
		// For now, we'll need to pass the file content directly or upload to storage first
		const fileUrl = formData.get('fileUrl') as string;

		if (!fileUrl) {
			throw error(
				400,
				'fileUrl is required. Upload the file to storage first and provide the URL.'
			);
		}

		// Process with OCR
		const ocrService = new OcrService();
		const ocrData = await ocrService.extractFromUrl(fileUrl, mimeType);

		return json({
			mimeType,
			category,
			ocrData
		});
	} catch (err) {
		console.error('OCR API error:', err);

		// Re-throw SvelteKit errors
		if (err && typeof err === 'object' && 'status' in err) {
			throw err;
		}

		// Handle other errors
		const message = err instanceof Error ? err.message : 'Unknown error occurred';
		throw error(500, `OCR processing failed: ${message}`);
	}
};

