1	// Mistral OCR service wrapper
2	// deno-lint-ignore-file no-explicit-any
3	
4	export interface OcrResult {
5		transaction_date: string | null;
6		// #{#rdc2a} Verbatim printed date (e.g. "25/06/05"), un-interpreted for re-parsing.
7		raw_date_text: string | null;
8		total_amount: number | null;
9		tax: number | null;
10		merchant_name: string | null;
11		currency: string | null;
12		credit_card_name: string | null;
13		credit_card_last_4: string | null;
14	}
15	
16	/**
17	 * Extracts receipt fields from an image/PDF URL using Mistral's vision model.
18	 * Uses the chat completion API with pixtral-12b-2409 (same approach as OcrService.ts).
19	 * PDFs use document_url, images use image_url.
20	 * Note: Requires Deno.env to have MISTRAL_API_KEY.
21	 */
22	export async function ocrFromUrl(fileUrl: string, mimeType: string): Promise<OcrResult> {
23		const apiKey = (globalThis as any).Deno?.env?.get?.('MISTRAL_API_KEY');
24		if (!apiKey) throw new Error('MISTRAL_API_KEY not set');
25	
26		// Determine content type based on MIME type (matches OcrService.ts pattern)
27		const isPdf = mimeType.toLowerCase().includes('pdf');
28		const contentType = isPdf ? 'document_url' : 'image_url';
29		const urlKey = isPdf ? 'document_url' : 'image_url';
30	
31		console.log(`OCR processing ${isPdf ? 'PDF' : 'image'}: ${fileUrl.substring(0, 80)}...`);
32	
33		const chatRes = await fetch('https://api.mistral.ai/v1/chat/completions', {
34			method: 'POST',
35			headers: {
36				Authorization: `Bearer ${apiKey}`,
37				'Content-Type': 'application/json'
38			},
39			body: JSON.stringify({
40				model: 'pixtral-12b-2409',
41				messages: [
42					{
43						role: 'user',
44						content: [
45							{
46								type: 'text',
47								text: 'Extract fields from the receipt. Respond as JSON with keys: transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed on the receipt, verbatim — keep the original separators and digits, do not reinterpret), total_amount (number), tax (number), merchant_name (string), currency (ISO 4217), credit_card_name (string), credit_card_last_4 (string). Default currency to CAD unless the receipt explicitly states a different currency. A bare "$" sign means CAD.'
48							},
49							{
50								type: contentType,
51								[urlKey]: fileUrl
52							}
53						]
54					}
55				],
56				response_format: { type: 'json_object' }
57			})
58		});
59	
60		if (!chatRes.ok) {
61			const errorText = await chatRes.text();
62			throw new Error(`Mistral vision API failed ${chatRes.status}: ${errorText}`);
63		}
64	
65		const data = await chatRes.json();
66		let content: any = {};
67		try {
68			const text = data?.choices?.[0]?.message?.content ?? '{}';
69			content = typeof text === 'string' ? JSON.parse(text) : text;
70		} catch {}
71	
72		const toNum = (v: any): number | null => {
73			if (typeof v === 'number') return Number.isFinite(v) ? v : null;
74			if (typeof v === 'string') {
75				const n = parseFloat(v.replace(/[^0-9.\-]/g, ''));
76				return Number.isFinite(n) ? n : null;
77			}
78			return null;
79		};
80	
81		return {
82			transaction_date: content?.transaction_date ?? null,
83			raw_date_text: content?.raw_date_text ?? null,
84			total_amount: toNum(content?.total_amount),
85			tax: toNum(content?.tax),
86			merchant_name: content?.merchant_name ?? null,
87			currency: content?.currency ?? null,
88			credit_card_name: content?.credit_card_name ?? null,
89			credit_card_last_4: content?.credit_card_last_4 ?? null
90		};
91	}
92	
93	/**
94	 * Processes email text with Mistral to extract receipt information.
95	 * Returns receipt data if found, or null if no receipt detected.
96	 */
97	export async function processEmailText(emailText: string): Promise<OcrResult | null> {
98		const apiKey = (globalThis as any).Deno?.env?.get?.('MISTRAL_API_KEY');
99		if (!apiKey) throw new Error('MISTRAL_API_KEY not set');
100	
101		console.log('=== Sending text to Mistral (pixtral-12b) ===');
102		console.log('Text length:', emailText.length);
103		console.log('Text preview (first 500 chars):', emailText.substring(0, 500));
104		console.log('============================================');
105	
106		const res = await fetch('https://api.mistral.ai/v1/chat/completions', {
107			method: 'POST',
108			headers: {
109				Authorization: `Bearer ${apiKey}`,
110				'Content-Type': 'application/json'
111			},
112			body: JSON.stringify({
113				model: 'pixtral-12b-2409',
114				messages: [
115					{
116						role: 'system',
117						content:
118							'You are a receipt analyzer. Analyze the provided text and determine if it contains receipt information. If it does, extract the receipt fields. If it does not contain receipt information, respond with {"is_receipt": false}.'
119					},
120					{
121						role: 'user',
122						content: `Analyze this email text and extract receipt information if present. Return JSON with: is_receipt (boolean), transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed in the email, verbatim — keep original separators and digits, do not reinterpret), total_amount, tax, merchant_name, currency (ISO 4217, default CAD unless explicitly stated otherwise — a bare "$" means CAD), credit_card_name, credit_card_last_4.\n\nEmail text:\n${emailText}`
123					}
124				],
125				response_format: { type: 'json_object' }
126			})
127		});
128	
129		if (!res.ok) {
130			console.error('Mistral API error:', res.status, await res.text());
131			throw new Error(`Mistral API failed ${res.status}`);
132		}
