  </text>
</svg>`;

	// Encode the SVG as UTF-8 bytes
	const encoder = new TextEncoder();
	return encoder.encode(svgContent);
}

function escapeXml(unsafe: string): string {
	return unsafe
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&apos;');
}

