import { describe, it, expect } from 'vitest';
import { errText } from './errText.ts';

/**
 * Unit tests for errText — the catch-value → string collapser the Resend webhook
 * uses for logging and its `processingErrors` list. Covers each branch: Error,
 * error-shaped object, bare string, and non-message values, including the ones
 * where JSON.stringify alone would not yield a string.
 */
describe('errText', () => {
	it('returns the message of an Error', () => {
		expect(errText(new Error('boom'))).toBe('boom');
	});

	it('returns a string `message` off a plain error-shaped object', () => {
		expect(errText({ message: 'db insert failed', code: '23505' })).toBe('db insert failed');
	});

	it('serialises an object whose `message` is not a string', () => {
		expect(errText({ message: 42, code: 'X' })).toBe('{"message":42,"code":"X"}');
	});

	it('serialises an object with no `message`', () => {
		expect(errText({ status: 500 })).toBe('{"status":500}');
	});

	it('returns a bare string unchanged', () => {
		expect(errText('plain failure')).toBe('plain failure');
	});

	it('stringifies primitives', () => {
		expect(errText(123)).toBe('123');
		expect(errText(null)).toBe('null');
	});

	it('always returns a string, even when JSON.stringify would yield undefined', () => {
		// JSON.stringify(undefined) === undefined; errText must still return a string.
		expect(errText(undefined)).toBe('undefined');
		expect(typeof errText(() => {})).toBe('string');
	});
});

