/**
 * Family Category Visibility Test Suite
 *
 * Tests for #{#fcv1a} - Family Category Visibility
 * Specification: specs/specifications/family-category-visibility.md
 * Authority: system
 * Priority: Critical
 *
 * This test suite verifies that:
 * 1. Categories are family-scoped (not user-scoped)
 * 2. Category assignments are visible to all active family members
 * 3. Vendor rules are shared across family members
 * 4. Only active members can access family data
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createClient } from '@supabase/supabase-js';
import type { TestDatabase } from './builders/testDatabase';

// Test configuration
const SUPABASE_URL = process.env.PUBLIC_SUPABASE_URL || '';
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';

// Skip tests if Supabase is not configured
const describeIf = (condition: boolean) => (condition ? describe : describe.skip);

describeIf(Boolean(SUPABASE_URL && SUPABASE_SERVICE_KEY))(
	'Family Category Visibility Integration Tests',
	() => {
		let supabase: ReturnType<typeof createClient<TestDatabase>>;

		// Test data IDs
		let testFamilyId: string;
		let testUser1Id: string;
		let testUser2Id: string;
		let testUser3Id: string; // Removed member
		let testCategoryId: string;
		let testReceiptId: string | undefined; // No test creates a receipt yet; cleanup guards on it

		beforeEach(async () => {
			supabase = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY);

			// Create test family
			const { data: family, error: familyError } = await supabase
				.from('families')
				.insert({ name: 'Test Family for Category Visibility' })
				.select()
				.single();

			if (familyError) throw familyError;
			testFamilyId = family.id;

			// Create test users
			const { data: user1, error: user1Error } = await supabase.auth.admin.createUser({
				email: `test-user1-${Date.now()}@example.com`,
				password: 'testpassword123',
				email_confirm: true
			});
			if (user1Error) throw user1Error;
			testUser1Id = user1.user.id;

			const { data: user2, error: user2Error } = await supabase.auth.admin.createUser({
				email: `test-user2-${Date.now()}@example.com`,
				password: 'testpassword123',
				email_confirm: true
			});
			if (user2Error) throw user2Error;
			testUser2Id = user2.user.id;

			const { data: user3, error: user3Error } = await supabase.auth.admin.createUser({
				email: `test-user3-${Date.now()}@example.com`,
				password: 'testpassword123',
				email_confirm: true
			});
			if (user3Error) throw user3Error;
			testUser3Id = user3.user.id;

			// Add users to family
			await supabase.from('family_members').insert([
				{
					family_id: testFamilyId,
					user_id: testUser1Id,
					status: 'active',
					role: 'owner',
					is_default: true
				},
				{
					family_id: testFamilyId,
					user_id: testUser2Id,
					status: 'active',
					role: 'member',
					is_default: true
				},
				{
					family_id: testFamilyId,
					user_id: testUser3Id,
					status: 'removed',
					role: 'member',
					is_default: false
				}
			]);
		});

		afterEach(async () => {
			// Cleanup test data
			if (testCategoryId) {
				await supabase.from('categories').delete().eq('id', testCategoryId);
			}
			if (testReceiptId) {
				await supabase.from('receipts').delete().eq('id', testReceiptId);
			}
			if (testFamilyId) {
				await supabase.from('family_members').delete().eq('family_id', testFamilyId);
				await supabase.from('families').delete().eq('id', testFamilyId);
			}
			if (testUser1Id) {
				await supabase.auth.admin.deleteUser(testUser1Id);
			}
			if (testUser2Id) {
				await supabase.auth.admin.deleteUser(testUser2Id);
			}
			if (testUser3Id) {
				await supabase.auth.admin.deleteUser(testUser3Id);
			}
		});

		describe('#{#fcv1b} - Family Category Visibility', () => {
			it('should allow all active family members to see categories created by any member', async () => {
				// User 1 creates a category
				const { data: user1Session } = await supabase.auth.signInWithPassword({
					email: `test-user1-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user1Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user1Client.auth.setSession({
					access_token: user1Session.session!.access_token,
					refresh_token: user1Session.session!.refresh_token
				});

				const { data: category, error: createError } = await user1Client
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Test Groceries', color: '#10B981' })
					.select()
					.single();

				expect(createError).toBeNull();
				expect(category).toBeDefined();
				testCategoryId = category!.id;

				// User 2 should be able to see the category
				const { data: user2Session } = await supabase.auth.signInWithPassword({
					email: `test-user2-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user2Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user2Client.auth.setSession({
					access_token: user2Session.session!.access_token,
					refresh_token: user2Session.session!.refresh_token
				});

				const { data: categories, error: fetchError } = await user2Client
					.from('categories')
					.select('*')
					.eq('family_id', testFamilyId);

				expect(fetchError).toBeNull();
				expect(categories).toHaveLength(1);
				expect(categories![0].name).toBe('Test Groceries');
			});

			it('should prevent removed family members from seeing categories', async () => {
				// Create category as admin
				const { data: category, error: createError } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Test Category', color: '#10B981' })
					.select()
					.single();

				expect(createError).toBeNull();
				testCategoryId = category!.id;

				// User 3 (removed) should NOT be able to see the category
				const { data: user3Session } = await supabase.auth.signInWithPassword({
					email: `test-user3-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user3Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user3Client.auth.setSession({
					access_token: user3Session.session!.access_token,
					refresh_token: user3Session.session!.refresh_token
				});

				const { data: categories, error: fetchError } = await user3Client
					.from('categories')
					.select('*')
					.eq('family_id', testFamilyId);

				// Should return empty array due to RLS
				expect(fetchError).toBeNull();
				expect(categories).toHaveLength(0);
			});

			it('should enforce unique category names per family', async () => {
				// User 1 creates a category
				const { data: category1, error: error1 } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
					.select()
					.single();

				expect(error1).toBeNull();
				testCategoryId = category1!.id;

				// User 2 tries to create same category (should fail)
				const { error: error2 } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'groceries', color: '#FF0000' });

				expect(error2).toBeDefined();
				expect(error2?.code).toBe('23505'); // Unique constraint violation
			});
		});

		describe('#{#fcv2a} - Active Member Filter', () => {
			it('should only allow active members to view transactions', async () => {
				// Create transaction as admin
				const { data: transaction, error: createError } = await supabase
					.from('transactions')
					.insert({
						family_id: testFamilyId,
						transaction_date: '2026-01-01',
						vendor_name: 'Test Vendor',
						amount: 100.0,
						credit_card_type: 'Visa'
					})
					.select()
					.single();

				expect(createError).toBeNull();

				// Active user should see it
				const { data: user1Session } = await supabase.auth.signInWithPassword({
					email: `test-user1-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user1Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user1Client.auth.setSession({
					access_token: user1Session.session!.access_token,
					refresh_token: user1Session.session!.refresh_token
				});

				const { data: transactions1 } = await user1Client
					.from('transactions')
					.select('*')
					.eq('family_id', testFamilyId);

				expect(transactions1).toHaveLength(1);

				// Removed user should NOT see it
				const { data: user3Session } = await supabase.auth.signInWithPassword({
					email: `test-user3-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user3Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user3Client.auth.setSession({
					access_token: user3Session.session!.access_token,
					refresh_token: user3Session.session!.refresh_token
				});

				const { data: transactions3 } = await user3Client
					.from('transactions')
					.select('*')
					.eq('family_id', testFamilyId);

				expect(transactions3).toHaveLength(0);

				// Cleanup
				await supabase.from('transactions').delete().eq('id', transaction!.id);
			});
		});

		describe('#{#fcv3a} - Vendor Rule Sharing', () => {
			it('should allow vendor rules to apply across all family members', async () => {
				// User 1 creates a vendor rule
				const { data: category } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
					.select()
					.single();

				testCategoryId = category!.id;

				const { data: rule, error: ruleError } = await supabase
					.from('vendor_category_rules')
					.insert({
						family_id: testFamilyId,
						vendor_pattern: 'costco',
						category_id: testCategoryId
					})
					.select()
					.single();

				expect(ruleError).toBeNull();
				expect(rule).toBeDefined();

				// User 2 should be able to see the rule
				const { data: user2Session } = await supabase.auth.signInWithPassword({
					email: `test-user2-${Date.now()}@example.com`,
					password: 'testpassword123'
				});

				const user2Client = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
					auth: { persistSession: false }
				});
				await user2Client.auth.setSession({
					access_token: user2Session.session!.access_token,
					refresh_token: user2Session.session!.refresh_token
				});

				const { data: rules, error: fetchError } = await user2Client
					.from('vendor_category_rules')
					.select('*')
					.eq('family_id', testFamilyId);

				expect(fetchError).toBeNull();
				expect(rules).toHaveLength(1);
				expect(rules![0].vendor_pattern).toBe('costco');

				// Cleanup
				await supabase.from('vendor_category_rules').delete().eq('id', rule!.id);
			});

			it('should enforce unique vendor patterns per family', async () => {
				const { data: category } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
					.select()
					.single();

				testCategoryId = category!.id;

				// Create first rule
				const { data: rule1, error: error1 } = await supabase
					.from('vendor_category_rules')
					.insert({
						family_id: testFamilyId,
						vendor_pattern: 'walmart',
						category_id: testCategoryId
					})
					.select()
					.single();

				expect(error1).toBeNull();

				// Try to create duplicate (should fail)
				const { error: error2 } = await supabase.from('vendor_category_rules').insert({
					family_id: testFamilyId,
					vendor_pattern: 'walmart',
					category_id: testCategoryId
				});

				expect(error2).toBeDefined();
				expect(error2?.code).toBe('23505'); // Unique constraint violation

				// Cleanup
				await supabase.from('vendor_category_rules').delete().eq('id', rule1!.id);
			});
		});

		describe('#{#fcv4a} - Category Name Uniqueness', () => {
			it('should enforce case-insensitive unique category names per family', async () => {
				// Create category with lowercase
				const { data: category1, error: error1 } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'groceries', color: '#10B981' })
					.select()
					.single();

				expect(error1).toBeNull();
				testCategoryId = category1!.id;

				// Try to create with different case (should fail)
				const { error: error2 } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'GROCERIES', color: '#FF0000' });

				expect(error2).toBeDefined();
				expect(error2?.code).toBe('23505');

				// Try with mixed case (should also fail)
				const { error: error3 } = await supabase
					.from('categories')
					.insert({ family_id: testFamilyId, name: 'Groceries', color: '#0000FF' });

				expect(error3).toBeDefined();
				expect(error3?.code).toBe('23505');
			});
		});

		describe('#{#fcv8a} - Transaction Visibility Testing', () => {
			it('should allow transaction exclusion status to be visible to all active members', async () => {
				// Create excluded transaction
				const { data: transaction, error: createError } = await supabase
					.from('transactions')
					.insert({
						family_id: testFamilyId,
						transaction_date: '2026-01-01',
